:root {
  color-scheme: dark;
  --px-obsidian: #07090C;
  --px-graphite: #12171D;
  --px-charcoal: #1B222A;
  --px-deep-navy: #0D1420;
  --px-champagne-gold: #C9A86A;
  --px-gold-muted: #A88952;
  --px-founder-ghost-gray: #A1A7AE;
  --px-founder-ghost-gray-dark: #6F7880;
  --px-founder-ghost-gray-soft: rgba(161, 167, 174, 0.12);
  --px-silver: #D8DEE5;
  --px-semantic-amber: #D6A344;
  --px-crimson: #B43A45;
  --px-emerald: #14966A;
  --px-black: var(--px-obsidian);
  --px-graphite: #12171D;
  --px-charcoal: #1B222A;
  --px-ivory: #F3EFE6;
  --px-paper: #EFE3CF;
  --px-gold: var(--px-champagne-gold);
  --px-antique-gold: var(--px-gold-muted);
  --px-bronze: #7A5A28;
  --px-sage: #6F8068;
  --px-risk: var(--px-crimson);
  --px-muted: #929BA5;
  --px-radius-xs: 8px;
  --px-radius-sm: 10px;
  --px-radius-md: 16px;
  --px-radius-lg: 22px;
  --px-radius-xl: 28px;
  --px-border-soft: rgba(212, 175, 55, 0.18);
  --px-border-muted: rgba(246, 240, 228, 0.10);
  --px-border-quiet: rgba(168, 160, 150, 0.16);
  --px-card: rgba(17, 17, 17, 0.92);
  --px-card-raised: rgba(26, 23, 18, 0.88);
  --px-card-quiet: rgba(246, 240, 228, 0.035);
  --px-shadow-card: 0 18px 60px rgba(0, 0, 0, 0.32);
  --px-shadow-soft: 0 10px 30px rgba(0, 0, 0, 0.22);
  --px-transition-fast: 150ms ease;
  --px-transition: 220ms ease;
  --px-z-sidebar: 30;
  --px-z-topbar: 20;
  --bg: var(--px-black);
  --panel: var(--px-graphite);
  --panel-2: var(--px-charcoal);
  --line: var(--px-border-muted);
  --text: var(--px-ivory);
  --muted: var(--px-muted);
  --green: var(--px-sage);
  --red: var(--px-risk);
  --amber: var(--px-gold);
  --teal: var(--px-muted);
  --blue: var(--px-sage);
  --violet: var(--px-antique-gold);
  --black: var(--px-black);
  --radius: var(--px-radius-md);
  --sidebar-width: 290px;  /* Compact sidebar */
  --page-padding: clamp(16px, 1.5vw, 28px);
  --card-padding: 14px;
  --section-gap: 14px;
  --font-base: 13px;
  --font-small: 10.5px;
  --glow-cyan: rgba(168, 160, 150, 0.10);
  --glow-gold: rgba(212, 175, 55, 0.14);
  --glow-violet: rgba(182, 138, 58, 0.10);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

/* Intelligence Core controls must remain dark inside the historical broad light-button theme. */
body[data-active-view="alerts"] #alerts.active .pic-core .pic-candidate-tabs button {
  min-height: 92px !important;
  padding: 12px !important;
  border: 1px solid rgba(255, 255, 255, 0.075) !important;
  border-radius: 11px !important;
  background: rgba(255, 255, 255, 0.018) !important;
  color: #ece8df !important;
  box-shadow: none !important;
  transform: none !important;
}

body[data-active-view="alerts"] #alerts.active .pic-core .pic-candidate-tabs button:hover,
body[data-active-view="alerts"] #alerts.active .pic-core .pic-candidate-tabs button:focus-visible,
body[data-active-view="alerts"] #alerts.active .pic-core .pic-candidate-tabs button.is-active {
  border-color: rgba(221, 185, 95, 0.55) !important;
  background: linear-gradient(145deg, rgba(212, 175, 55, 0.12), rgba(255, 255, 255, 0.02)) !important;
  color: #f4efe4 !important;
  box-shadow: inset 0 1px rgba(255, 248, 224, 0.04) !important;
  transform: none !important;
}

@media (max-width: 760px) {
  body[data-active-view="alerts"] #alerts.active .pic-core .pic-candidate-tabs button {
    min-height: 76px !important;
  }
}

/* DESIGN SYSTEM CLASSES */
.pc-panel {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: var(--card-padding);
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.35);
  position: relative;
  overflow: hidden;
}
.pc-card {
  background: var(--panel-2);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 12px;
  transition: all 0.2s ease;
}
.pc-card:hover {
  border-color: rgba(0, 229, 255, 0.3);
  box-shadow: 0 0 15px var(--glow-cyan);
}
.pc-status-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 6px;
  border-radius: 2px;
  font-size: 9px;
  text-transform: uppercase;
  font-weight: 700;
  border: 1px solid transparent;
  font-family: monospace;
}
.pc-status-chip.static { border-color: rgba(138, 155, 168, 0.2); color: var(--muted); background: rgba(138, 155, 168, 0.05); }
.pc-status-chip.prototype { border-color: rgba(167, 139, 250, 0.3); color: var(--violet); background: rgba(167, 139, 250, 0.05); }
.pc-status-chip.research { border-color: rgba(167, 139, 250, 0.3); color: var(--violet); background: rgba(167, 139, 250, 0.05); }
.pc-status-chip.future-adapter { border-color: rgba(255, 61, 0, 0.3); color: #ff9100; background: rgba(255, 97, 0, 0.05); }
.pc-status-chip.local-state { border-color: rgba(0, 229, 255, 0.3); color: var(--teal); background: rgba(0, 229, 255, 0.05); }
.pc-status-chip.manual-review { border-color: rgba(212, 175, 55, 0.3); color: var(--amber); background: rgba(212, 175, 55, 0.05); }
.pc-status-chip.no-live-data { border-color: rgba(255, 61, 0, 0.3); color: var(--red); background: rgba(255, 61, 0, 0.05); }
.pc-status-chip.no-broker { border-color: rgba(255, 61, 0, 0.3); color: var(--red); background: rgba(255, 61, 0, 0.05); }
.pc-status-chip.mock-ready { border-color: rgba(0, 230, 118, 0.3); color: var(--green); background: rgba(0, 230, 118, 0.05); }
.pc-status-chip.adapter-ready { border-color: rgba(41, 121, 255, 0.3); color: var(--blue); background: rgba(41, 121, 255, 0.05); }

.pc-action-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 6px 12px;
  background: rgba(212, 175, 55, 0.05);
  border: 1px solid rgba(212, 175, 55, 0.3);
  color: var(--amber);
  text-transform: uppercase;
  font-size: 10px;
  font-weight: 700;
  cursor: pointer;
  border-radius: var(--radius);
  transition: all 0.15s ease;
  font-family: monospace;
}
.pc-action-btn:hover {
  background: rgba(212, 175, 55, 0.12);
  border-color: var(--amber);
  box-shadow: 0 0 10px var(--glow-gold);
}
.pc-action-btn.secondary {
  background: rgba(0, 229, 255, 0.03);
  border-color: rgba(0, 229, 255, 0.25);
  color: var(--teal);
}
.pc-action-btn.secondary:hover {
  background: rgba(0, 229, 255, 0.08);
  border-color: var(--teal);
  box-shadow: 0 0 10px var(--glow-cyan);
}
.pc-action-btn.risk {
  background: rgba(255, 61, 0, 0.03);
  border-color: rgba(255, 61, 0, 0.25);
  color: var(--red);
}
.pc-action-btn.risk:hover {
  background: rgba(255, 61, 0, 0.08);
  border-color: var(--red);
  box-shadow: 0 0 10px rgba(255, 61, 0, 0.2);
}

.pc-terminal-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 12px;
}
.pc-agent-card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 12px;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 10px;
}
.pc-agent-card::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  width: 3px;
  height: 100%;
  background: var(--line);
}
.pc-agent-card.critical::before { background: var(--red); }
.pc-agent-card.high::before { background: var(--amber); }
.pc-agent-card.medium::before { background: var(--blue); }
.pc-agent-card.low::before { background: var(--muted); }

.pc-metric-card {
  background: rgba(0, 0, 0, 0.2);
  border: 1px solid var(--line);
  padding: 10px;
  border-radius: var(--radius);
  text-align: left;
}
.pc-metric-card strong {
  display: block;
  font-size: 18px;
  color: var(--text);
  font-family: monospace;
}
.pc-metric-card span {
  font-size: 9.5px;
  color: var(--muted);
  text-transform: uppercase;
}

.pc-ticker-strip {
  display: flex;
  overflow-x: auto;
  gap: 6px;
  padding: 6px 0;
  white-space: nowrap;
}
.pc-ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: rgba(0,0,0,0.3);
  border: 1px solid var(--line);
  padding: 4px 8px;
  font-size: 10px;
  font-family: monospace;
}
.truth-pill {
  font-size: 9.5px;
  font-family: monospace;
  padding: 2px 6px;
  background: rgba(255, 61, 0, 0.06);
  border: 1px solid rgba(255, 61, 0, 0.25);
  color: var(--red);
  font-weight: 700;
  text-transform: uppercase;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  font-size: var(--font-base);
  background:
    linear-gradient(115deg, rgba(73, 242, 143, 0.07), transparent 32%),
    linear-gradient(180deg, rgba(66, 217, 200, 0.06), transparent 45%),
    radial-gradient(circle at 78% 12%, rgba(255, 190, 77, 0.09), transparent 24%),
    radial-gradient(circle at 50% 100%, rgba(185, 146, 255, 0.08), transparent 30%),
    var(--bg);
  color: var(--text);
}

button,
input,
textarea,
select {
  font: inherit;
}

button {
  border: 1px solid var(--line);
  color: var(--text);
  background: #1c1f1b;
  border-radius: var(--radius);
  padding: 10px 12px;
  cursor: pointer;
}

button:hover {
  border-color: var(--teal);
}

.shell {
  min-height: 100vh;
  display: grid;
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
}

.rail {
  border-right: 1px solid var(--line);
  background: rgba(8, 9, 7, 0.82);
  padding: 24px;
  position: sticky;
  top: 0;
  height: 100vh;
  overflow-y: auto;
}

.brand {
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-items: flex-start;
  padding: 14px;
  border: 1px solid rgba(66, 217, 200, 0.18);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.03);
}

.home-brand {
  color: var(--text);
  text-decoration: none;
  transition: border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

.home-brand:hover {
  border-color: rgba(73, 242, 143, 0.56);
  background: rgba(73, 242, 143, 0.07);
  transform: translateY(-1px);
}

.brand strong {
  font-size: 19px;
  line-height: 1.05;
}

.brand strong,
.brand small {
  display: block;
}

.brand small,
.label,
.eyebrow {
  color: var(--muted);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0;
}

.mark {
  display: grid;
  place-items: center;
  width: 108px;
  height: 108px;
  flex: 0 0 108px;
  align-self: center;
  background: radial-gradient(circle at 50% 42%, rgba(66, 217, 200, 0.1), rgba(7, 9, 8, 0.58) 64%);
  border: 1px solid rgba(66, 217, 200, 0.42);
  color: var(--text);
  border-radius: 50%;
  font-weight: 900;
  overflow: hidden;
}

.mark img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  border-radius: 50%;
}

.nav {
  display: grid;
  gap: 8px;
  margin: 30px 0;
}

.nav-button {
  display: flex;
  align-items: center;
  gap: 10px;
  text-align: left;
  min-height: 44px;
  padding: 12px 14px;
  font-size: 15px;
  font-weight: 800;
}

.nav-button span {
  display: grid;
  place-items: center;
  flex: 0 0 30px;
  height: 26px;
  border: 1px solid rgba(66, 217, 200, 0.28);
  border-radius: 8px;
  color: var(--amber);
  background: rgba(8, 10, 13, 0.72);
  font-size: 11px;
  font-weight: 900;
}

.nav-button.active {
  border-color: var(--green);
  color: var(--green);
  background: rgba(73, 242, 143, 0.08);
}

.nav-button.active span {
  border-color: rgba(73, 242, 143, 0.58);
  color: var(--green);
}

.nav-button.secondary {
  color: var(--muted);
  font-size: 13px;
  padding: 8px 10px;
}

.rail-card {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px;
  background: var(--panel);
}

.rail-card p {
  color: var(--muted);
  line-height: 1.45;
  margin-bottom: 0;
}

#command > .control-band,
#command > .metrics,
#command > .selected-pulse,
#command > .split,
#command > .panel {
  display: none;
}

.rail-quote {
  display: grid;
  gap: 10px;
  margin-top: 12px;
  padding: 16px;
  border: 1px solid rgba(255, 190, 77, 0.28);
  border-radius: var(--radius);
  background:
    linear-gradient(135deg, rgba(255, 190, 77, 0.1), rgba(66, 217, 200, 0.04)),
    rgba(10, 12, 10, 0.82);
  box-shadow: inset 0 0 32px rgba(255, 190, 77, 0.04);
}

.rail-quote p {
  margin: 0;
  color: var(--text);
  line-height: 1.45;
}

.rail-quote strong {
  color: var(--amber);
  font-size: 12px;
  text-transform: uppercase;
}

main {
  padding: var(--page-padding);
  min-width: 0;
  width: 100%;
  max-width: 1760px;
  margin: 0 auto;
}

.topbar,
.panel-head,
.control-band,
.check-hero,
.vision-hero,
.signal-hero {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.key-notes {
  display: grid;
  grid-template-columns: 220px 1fr;
  gap: 16px;
  margin: 12px 0;
  padding: 16px;
  border: 1px solid rgba(255, 190, 77, 0.35);
  border-radius: var(--radius);
  background: rgba(255, 190, 77, 0.08);
}

.key-notes h2,
.key-notes p {
  margin-bottom: 0;
}

.key-notes p {
  color: var(--text);
  line-height: 1.5;
}

.intelligence-zone {
  display: grid;
  gap: 14px;
}

.command-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(260px, 0.8fr);
  gap: 18px;
  align-items: stretch;
  margin: 16px 0;
  padding: 18px;
  border: 1px solid rgba(66, 217, 200, 0.34);
  border-radius: var(--radius);
  background:
    linear-gradient(135deg, rgba(73, 242, 143, 0.11), rgba(185, 146, 255, 0.08)),
    rgba(9, 13, 13, 0.9);
  box-shadow: inset 0 0 42px rgba(66, 217, 200, 0.05);
}

.command-hero.compact {
  grid-template-columns: 1fr auto;
}

.command-hero h2 {
  font-size: clamp(30px, 4vw, 56px);
}

.command-hero p {
  color: var(--muted);
  line-height: 1.55;
  max-width: 900px;
}

.command-status-grid,
.signal-badges,
.metric-strip,
.drawer-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(130px, 1fr));
  gap: 8px;
}

.command-status-grid span,
.signal-badges span,
.metric-strip article,
.drawer-stats span {
  border: 1px solid rgba(73, 242, 143, 0.22);
  border-radius: var(--radius);
  padding: 10px;
  background: rgba(0, 0, 0, 0.32);
  color: var(--muted);
}

.command-status-grid strong,
.metric-strip strong,
.drawer-stats strong {
  display: block;
  color: var(--green);
  font-size: 22px;
}

.ceo-command-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
}

.ceo-command-strip span {
  border: 1px solid rgba(255, 190, 77, 0.28);
  border-radius: 999px;
  padding: 8px 10px;
  color: var(--muted);
  background: rgba(255, 190, 77, 0.06);
}

.ceo-command-strip strong {
  color: var(--amber);
}

.strategic-hub-layout {
  display: grid;
  grid-template-columns: 260px minmax(520px, 1fr) 280px;
  gap: 14px;
  align-items: stretch;
}

.command-input-rail,
.command-agent-rail,
.vision-node-drawer {
  display: grid;
  align-content: start;
  gap: 8px;
  border: 1px solid rgba(66, 217, 200, 0.24);
  border-radius: var(--radius);
  padding: 12px;
  background: rgba(7, 10, 12, 0.88);
}

.strategic-command-map {
  position: relative;
  min-height: 680px;
  overflow: hidden;
  border: 1px solid rgba(73, 242, 143, 0.28);
  border-radius: var(--radius);
  background:
    linear-gradient(rgba(73, 242, 143, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(66, 217, 200, 0.05) 1px, transparent 1px),
    radial-gradient(circle at 50% 36%, rgba(255, 190, 77, 0.18), transparent 20%),
    radial-gradient(circle at 50% 58%, rgba(73, 242, 143, 0.15), transparent 28%),
    rgba(5, 8, 10, 0.95);
  background-size: 30px 30px, 30px 30px, auto, auto, auto;
}

.strategic-command-map::before {
  content: "";
  position: absolute;
  inset: 12px;
  border: 1px solid rgba(66, 217, 200, 0.16);
  border-radius: 18px;
  pointer-events: none;
  animation: habitatPulse 4s ease-in-out infinite;
}

.ceo-overseer,
.trading-hub-core {
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  display: grid;
  gap: 7px;
  text-align: center;
  z-index: 2;
}

.ceo-overseer {
  top: 46px;
  width: min(360px, 80%);
  border-color: rgba(255, 190, 77, 0.58);
  background: rgba(18, 13, 7, 0.88);
  box-shadow: 0 0 44px rgba(255, 190, 77, 0.16);
}

.ceo-overseer strong {
  color: var(--amber);
  font-size: 28px;
}

.trading-hub-core {
  top: 240px;
  width: min(520px, 86%);
  min-height: 190px;
  place-content: center;
  border-color: rgba(73, 242, 143, 0.58);
  background:
    radial-gradient(circle, rgba(73, 242, 143, 0.18), rgba(8, 12, 14, 0.9) 62%),
    rgba(8, 12, 14, 0.9);
  box-shadow: 0 0 70px rgba(73, 242, 143, 0.14);
}

.trading-hub-core strong {
  color: var(--green);
  font-size: 30px;
}

.plugins-access-row {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 18px;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 8px;
}

.command-node-card,
.agent-mini-node {
  display: grid;
  gap: 5px;
  width: 100%;
  text-align: left;
  padding: 10px;
  border-color: rgba(66, 217, 200, 0.22);
  background: rgba(13, 18, 19, 0.86);
}

.command-node-card span,
.agent-mini-node span,
.ceo-overseer span,
.trading-hub-core span,
.ceo-overseer small,
.trading-hub-core small {
  color: var(--muted);
}

.command-node-card.selected,
.agent-mini-node.selected {
  border-color: var(--green);
  box-shadow: 0 0 24px rgba(73, 242, 143, 0.14);
}

.command-node-card.input {
  border-left-color: var(--teal);
}

.command-node-card.page {
  border-left-color: var(--violet);
}

.command-node-card.system {
  border-left-color: var(--amber);
}

.flow-arrow {
  position: absolute;
  display: block;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--teal), transparent);
  opacity: 0.75;
  animation: flowPulse 2.4s ease-in-out infinite;
}

.flow-left {
  left: 8%;
  right: 56%;
  top: 50%;
}

.flow-right {
  left: 56%;
  right: 8%;
  top: 50%;
}

.flow-bottom {
  left: 30%;
  right: 30%;
  bottom: 145px;
}

.vision-detail-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 360px;
  gap: 14px;
}

.node-detail-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
}

.node-detail-grid div {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: var(--radius);
  padding: 10px;
  background: rgba(255, 255, 255, 0.03);
}

.node-detail-grid p {
  margin: 4px 0 0;
  color: var(--text);
}

.node-actions {
  margin-top: 12px;
}

@keyframes flowPulse {
  0%, 100% { opacity: 0.25; transform: scaleX(0.88); }
  50% { opacity: 0.9; transform: scaleX(1); }
}

@keyframes habitatPulse {
  0%, 100% { opacity: 0.45; }
  50% { opacity: 0.9; }
}

.command-map-grid,
.source-terminal-layout,
.tracker-layout,
.intelligence-split {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 14px;
}

