}

.loop-two { stroke: rgba(66, 217, 200, 0.44); animation-delay: -1.2s; }
.loop-three { stroke: rgba(185, 146, 255, 0.44); animation-delay: -2.2s; }

.agent-node {
  border-radius: 18px;
}

.agent-node::after {
  content: "";
  position: absolute;
  inset: -18px 20px auto 20px;
  height: 42px;
  border: 1px solid currentColor;
