  height: 86px;
  margin: 10px 0;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(66, 217, 200, 0.12), transparent 65%);
}

.network-orbits::before,
.network-orbits::after {
  content: "";
  position: absolute;
  inset: 12px 22%;
  border: 1px solid rgba(66, 217, 200, 0.22);
  border-radius: 50%;
  animation: orbitPulse 4s ease-in-out infinite;
}

.network-orbits::after {
  inset: 24px 12%;
  border-color: rgba(255, 190, 77, 0.22);
  animation-delay: -1.5s;
}

.network-orbits span {
  position: absolute;
  width: 13px;
  height: 13px;
  border-radius: 50%;
  background: var(--teal);
  box-shadow: 0 0 18px var(--teal);
}

.network-orbits span:nth-child(1) { left: 12%; top: 45%; }
.network-orbits span:nth-child(2) { left: 34%; top: 14%; background: var(--violet); }
.network-orbits span:nth-child(3) { left: 55%; top: 52%; background: var(--amber); }
.network-orbits span:nth-child(4) { left: 78%; top: 22%; background: var(--green); }
.network-orbits span:nth-child(5) { left: 67%; top: 72%; background: var(--red); }

@keyframes rotateGlobe {
  to { transform: rotate(360deg); }
}

@keyframes floorPulse {
  50% { transform: scale(1.05); opacity: 0.56; }
}

@keyframes floorOperator {
  50% { filter: brightness(1.35); transform: rotate(calc(var(--i) * 16deg)) translateY(-84px); }
}

@keyframes podActiveGlow {
  50% { filter: brightness(1.18); }
}

@keyframes statusShimmer {
  50% { opacity: 0.62; transform: translateY(-4px); }
}

@keyframes travelPath {
  to { offset-distance: 100%; }
}

@keyframes cubeHandoff {
  50% { transform: translateY(-16px) rotate(45deg); filter: brightness(1.35); }
}

@keyframes pathFlow {
  to { stroke-dashoffset: -28; }
}

@keyframes pulse {
  0%, 100% { opacity: 0.68; transform: scale(0.96); }
  50% { opacity: 1; transform: scale(1.08); }
}

@keyframes agentPatrolOne {
  0%, 100% { transform: translate(-50%, -50%) translate3d(0, 0, 0); }
  35% { transform: translate(-50%, -50%) translate3d(24vw, 19vh, 0); }
  68% { transform: translate(-50%, -50%) translate3d(10vw, 42vh, 0); }
}

@keyframes agentPatrolTwo {
  0%, 100% { transform: translate(-50%, -50%) translate3d(0, 0, 0); }
  38% { transform: translate(-50%, -50%) translate3d(-24vw, 12vh, 0); }
  72% { transform: translate(-50%, -50%) translate3d(-8vw, 39vh, 0); }
}

@keyframes agentPatrolThree {
  0%, 100% { transform: translate(-50%, -50%) translate3d(0, 0, 0); }
  42% { transform: translate(-50%, -50%) translate3d(20vw, -28vh, 0); }
  76% { transform: translate(-50%, -50%) translate3d(42vw, -8vh, 0); }
}

@keyframes agentPatrolFour {
  0%, 100% { transform: translate(-50%, -50%) translate3d(0, 0, 0); }
  25% { transform: translate(-50%, -50%) translate3d(-10vw, 4vh, 0); }
  55% { transform: translate(-50%, -50%) translate3d(-26vw, -2vh, 0); }
  78% { transform: translate(-50%, -50%) translate3d(-8vw, -17vh, 0); }
}

@keyframes agentPatrolFive {
  0%, 100% { transform: translate(-50%, -50%) translate3d(0, 0, 0); }
  28% { transform: translate(-50%, -50%) translate3d(18vw, -10vh, 0); }
  58% { transform: translate(-50%, -50%) translate3d(31vw, -25vh, 0); }
  82% { transform: translate(-50%, -50%) translate3d(12vw, -32vh, 0); }
}

@keyframes characterBreathe {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-4px); }
}

@keyframes huddlePulse {
  50% { transform: translateY(-5px); box-shadow: 0 0 28px rgba(255, 190, 77, 0.18); }
}

