@keyframes float {
  0%, 100% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(0, -7px, 0); }
}

@keyframes dash {
  to { stroke-dashoffset: -12; }
}

@keyframes packet {
  0% { transform: translate3d(0, 0, 0) scale(0.7); opacity: 0; }
  20% { opacity: 1; }
  80% { opacity: 1; }
  100% { transform: translate3d(var(--tx), var(--ty), 0) scale(1); opacity: 0; }
}

@keyframes scanSweep {
  0%, 100% { transform: translateX(-80%) skewX(-10deg); opacity: 0; }
  18%, 70% { opacity: 1; }
  100% { transform: translateX(320%) skewX(-10deg); }
}

@keyframes droneFly {
  0% { transform: translate3d(-20px, 0, 0) rotate(-4deg); opacity: 0; }
  8%, 90% { opacity: 1; }
  50% { transform: translate3d(210px, 24px, 0) rotate(4deg); }
  100% { transform: translate3d(420px, -8px, 0) rotate(-2deg); opacity: 0; }
}

@keyframes orbitPulse {
  0%, 100% { transform: scale(0.94); opacity: 0.35; }
  50% { transform: scale(1.04); opacity: 0.72; }
}

@keyframes shimmer {
  0% { opacity: 0.45; }
  50% { opacity: 0.9; }
  100% { opacity: 0.45; }
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

