  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.staging-grid article {
  min-height: 210px;
  padding: 18px;
  border: 1px solid rgba(66, 217, 200, 0.22);
  border-radius: var(--radius);
  background: rgba(7, 11, 18, 0.82);
}

.staging-grid span {
  color: var(--amber);
  font-weight: 900;
}

.staging-grid p {
  color: var(--muted);
  line-height: 1.5;
}

.staging-grid i {
  display: block;
  height: 7px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--amber), var(--violet), var(--teal));
  background-size: 200% 100%;
  animation: gradientFlow 3s linear infinite;
}

.action-center-panel,
.agent-checklist-preview {
  margin-top: 12px;
}

.action-center {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.action-category {
  display: grid;
  gap: 8px;
  padding: 12px;
  border: 1px solid rgba(66, 217, 200, 0.18);
  border-radius: 8px;
  background: rgba(5, 8, 12, 0.72);
}

.action-category-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.action-category-head h3 {
  margin: 0;
}

.action-category-head span {
  color: var(--green);
  font-weight: 900;
}

.action-item,
.action-preview-item {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 10px;
  border: 1px solid rgba(244, 241, 232, 0.1);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.035);
}

.action-item input,
.action-preview-item input {
  margin-top: 4px;
  accent-color: var(--green);
}

.action-item strong,
.action-item small,
.action-item em,
.action-preview-item strong,
.action-preview-item small {
  display: block;
}

.action-item small,
.action-preview-item small {
  color: var(--teal);
  text-transform: uppercase;
  font-size: 11px;
}

.action-item em {
  margin-top: 4px;
  color: var(--muted);
  font-style: normal;
  line-height: 1.35;
}

.action-item.completed,
.action-preview-item.completed {
  opacity: 0.68;
  border-color: rgba(73, 242, 143, 0.26);
}

.action-item.completed strong,
.action-preview-item.completed strong {
  text-decoration: line-through;
}

.agent-checklist-preview-list {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

@media (max-width: 1060px) {
  .shell {
    grid-template-columns: 1fr;
  }

  .rail {
    position: static;
    height: auto;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .nav {
    grid-template-columns: repeat(7, 1fr);
  }

  .habitat-kpis {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .agent-overview-grid {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }

  .metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .split,
  .vision-layout,
  .habitat-shell,
  .agent-bottom-grid,
  .archive-layout,
  .founder-hero,
  .founder-section-grid,
  .founder-board,
  .founder-bottom-grid,
  .signal-grid,
  .signal-summary,
  .journal-grid {
    grid-template-columns: 1fr;
  }

  .archive-stats,
  .pipeline-steps,
  .archive-agent-grid,
  .staging-grid,
  .action-center,
  .agent-checklist-preview-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mini-card-grid {
    grid-template-columns: 1fr;
  }

  .journal-grid textarea,
  .journal-grid button {
    grid-column: auto;
  }
