@media (max-width: 680px) {
  main,
  .rail {
    padding: 14px;
  }

  .topbar,
  .panel-head,
  .control-band,
  .check-hero,
  .vision-hero,
  .signal-hero,
  .agent-hero,
  .archive-hero,
  .key-notes {
    align-items: stretch;
    flex-direction: column;
  }

  .key-notes,
  .selected-pulse,
  .mission-stats,
  .agent-detail-grid,
  .alert-blueprint {
    display: flex;
    flex-direction: column;
  }

  .agent-city {
    min-height: 860px;
  }

  .habitat-system-strip {
    grid-template-columns: 1fr;
  }

  .habitat-hud {
    position: relative;
    left: auto;
    top: auto;
    margin: 12px;
    width: auto;
  }

  .agent-node {
    width: 188px;
    margin-left: -94px;
    grid-template-columns: 42px 1fr;
  }

  .agent-avatar {
    width: 42px;
    height: 42px;
  }

  .habitat-kpis {
    grid-template-columns: 1fr;
  }

  .agent-overview-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .signal-stats,
  .plan-grid,
  .archive-toolbar,
  .source-table article,
  .archive-stats,
  .pipeline-steps,
  .archive-agent-grid,
  .staging-grid,
  .action-center,
  .agent-checklist-preview-list,
  .founder-quote-band,
  .vibe-row {
    grid-template-columns: 1fr;
  }

  .founder-image-panel::before {
    font-size: 34px;
  }

  .metrics {
    grid-template-columns: 1fr;
  }

  .contract {
    grid-template-columns: 48px 1fr 62px;
  }

.contract span:nth-child(n + 4) {
    display: none;
  }
}

