.dashboard-overview-grid,
.dashboard-stack-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  gap: 18px;
}

.dashboard-stack-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.dashboard-executive-card,
.dashboard-next-action {
  background:
    radial-gradient(circle at 18% 0%, rgba(245, 200, 76, 0.16), transparent 40%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.082), rgba(255, 255, 255, 0.03));
}

.dashboard-pulse-card {
  background:
    radial-gradient(circle at 82% 6%, rgba(56, 214, 255, 0.14), transparent 38%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.074), rgba(255, 255, 255, 0.026));
}

.dashboard-truth-card {
  min-width: 0;
}

.dashboard-status-list {
  display: grid;
  gap: 10px;
  margin-top: 14px;
}

.dashboard-status-list a,
.dashboard-status-list > span {
  display: grid;
  grid-template-columns: minmax(120px, 0.62fr) minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-soft);
  color: inherit;
  text-decoration: none;
}

.dashboard-status-list.compact > span {
  grid-template-columns: minmax(130px, 0.9fr) minmax(0, 1fr);
}

.dashboard-status-list a:hover strong,
.dashboard-status-list a:focus-visible strong {
  color: var(--gold);
}

.dashboard-status-list span,
.dashboard-status-list em {
  color: var(--text-muted);
  font-size: 12px;
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.dashboard-status-list strong {
  color: var(--text-main);
  font-size: 14.5px;
  line-height: 1.35;
  text-align: right;
}

.dashboard-metric-strip {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
  margin: 16px 0;
}

.dashboard-agent-preview {
  overflow: hidden;
}

.dashboard-agent-orbit {
  position: relative;
  min-height: 300px;
  margin: 12px 0 16px;
  border: 1px solid rgba(255, 255, 255, 0.09);
  border-radius: 16px;
  background:
    radial-gradient(circle at 50% 50%, rgba(245, 200, 76, 0.16), transparent 18%),
    radial-gradient(circle at 20% 22%, rgba(56, 214, 255, 0.12), transparent 28%),
    linear-gradient(180deg, rgba(10, 15, 22, 0.88), rgba(7, 10, 15, 0.94));
}

.dashboard-agent-orbit::before {
  content: "CEO B";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 94px;
  min-height: 66px;
  display: grid;
  place-items: center;
  transform: translate(-50%, -50%);
  border: 1px solid rgba(245, 200, 76, 0.38);
  border-radius: 14px;
  color: var(--gold);
  background: rgba(10, 13, 17, 0.9);
  font-weight: 900;
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.32);
}

.dashboard-agent-orbit span {
  --angle: calc(var(--i) * 51.42deg - 90deg);
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(138px, 36vw);
  padding: 10px;
  transform:
    translate(-50%, -50%)
    rotate(var(--angle))
    translateX(clamp(86px, 11vw, 138px))
    rotate(calc(var(--angle) * -1));
  border: 1px solid rgba(56, 214, 255, 0.18);
  border-radius: 12px;
  background: rgba(13, 18, 26, 0.88);
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.24);
}

.dashboard-agent-orbit strong {
  display: block;
  color: var(--text-main);
  font-size: 12.5px;
  line-height: 1.15;
}

.dashboard-agent-orbit em {
  display: block;
  margin-top: 4px;
  color: var(--text-muted);
  font-size: 11px;
  font-style: normal;
}

.dashboard-source-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.dashboard-pill-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 14px 0;
}

.dashboard-pill-list span {
  min-height: 32px;
  display: inline-flex;
  align-items: center;
  padding: 7px 11px;
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  color: var(--text-body);
  background: rgba(255, 255, 255, 0.045);
  font-size: 12px;
  font-weight: 800;
}

@media (max-width: 1280px) {
  .dashboard-command-grid,
  .dashboard-overview-grid,
  .dashboard-stack-grid,
  .dashboard-source-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .dashboard-truth-card,
  .dashboard-next-action {
    grid-column: 1 / -1;
  }
}

@media (max-width: 760px) {
  .dashboard-command-grid,
  .dashboard-overview-grid,
  .dashboard-stack-grid,
  .dashboard-source-grid,
  .dashboard-metric-strip {
    grid-template-columns: 1fr;
  }

  .dashboard-status-list a,
  .dashboard-status-list > span {
    grid-template-columns: 1fr;
    gap: 4px;
  }

  .dashboard-status-list strong {
    text-align: left;
  }

  .dashboard-agent-orbit {
    min-height: auto;
    display: grid;
    gap: 8px;
    padding: 74px 12px 12px;
  }

  .dashboard-agent-orbit span {
    position: relative;
    left: auto;
    top: auto;
    width: 100%;
    transform: none;
  }
}

/* Mission Control dashboard upgrade */
.mission-control-shell {
  gap: 22px;
}

.mission-hero {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.36fr) minmax(300px, 0.64fr);
  gap: 18px;
  align-items: stretch;
  overflow: hidden;
  padding: clamp(22px, 3vw, 36px);
  border: 1px solid rgba(245, 200, 76, 0.16);
  border-radius: 18px;
  background:
    linear-gradient(120deg, rgba(245, 200, 76, 0.13), transparent 30%),
    radial-gradient(circle at 82% 16%, rgba(56, 214, 255, 0.18), transparent 34%),
    radial-gradient(circle at 52% 100%, rgba(167, 139, 250, 0.12), transparent 32%),
    linear-gradient(180deg, rgba(16, 20, 28, 0.96), rgba(6, 8, 13, 0.98));
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.42);
}

.mission-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(rgba(255, 255, 255, 0.028) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.022) 1px, transparent 1px);
  background-size: 34px 34px;
  mask-image: linear-gradient(90deg, rgba(0, 0, 0, 0.7), transparent 78%);
}

.mission-hero-copy,
.mission-hero-panel {
  position: relative;
  z-index: 1;
}

.mission-hero h2 {
  margin: 8px 0 10px;
  color: var(--text-main);
  font-family: Anton, Inter, sans-serif;
  font-size: clamp(42px, 6vw, 86px);
  line-height: 0.95;
  letter-spacing: 0;
  text-transform: uppercase;
}

.mission-hero p {
  max-width: 980px;
  color: var(--text-body);
  font-size: clamp(15px, 1.3vw, 18px);
  line-height: 1.62;
}

.mission-hero-panel {
  display: grid;
  align-content: end;
  gap: 10px;
  min-height: 220px;
  padding: 18px;
  border: 1px solid rgba(56, 214, 255, 0.18);
  border-radius: 14px;
  background:
    radial-gradient(circle at 0% 0%, rgba(56, 214, 255, 0.16), transparent 42%),
    rgba(6, 10, 16, 0.68);
}

.mission-hero-panel strong {
  color: var(--gold);
  font-size: 18px;
  text-transform: uppercase;
}

.mission-hero-locks {
  display: grid;
  gap: 7px;
  margin-top: 8px;
}

.mission-hero-locks span {
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid rgba(245, 200, 76, 0.16);
  border-radius: 999px;
  color: var(--text-body);
  background: rgba(245, 200, 76, 0.05);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.mission-status-light,
.agent-state-dot {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: var(--green);
  box-shadow: 0 0 0 6px rgba(73, 242, 143, 0.08), 0 0 20px rgba(73, 242, 143, 0.48);
  animation: missionPulse 2.4s ease-in-out infinite;
}

@keyframes missionPulse {
  0%, 100% { opacity: 0.56; transform: scale(0.94); }
  50% { opacity: 1; transform: scale(1); }
}

.mission-stat-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.mission-stat-card {
  min-height: 112px;
  padding: 16px;
  border: 1px solid var(--border-soft);
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.062), rgba(255, 255, 255, 0.024)),
    rgba(8, 12, 18, 0.86);
}

.mission-stat-card span,
.mission-stat-card small {
  display: block;
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mission-stat-card strong {
  display: block;
  margin: 8px 0;
  color: var(--text-main);
  font-size: clamp(21px, 2.4vw, 34px);
  line-height: 1;
}

.mission-command-card,
.alerts-command-card,
.research-queue-card {
  background:
    radial-gradient(circle at 18% 0%, rgba(245, 200, 76, 0.18), transparent 42%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.086), rgba(255, 255, 255, 0.028));
}

.mission-motto {
  margin: 18px 0;
  padding: 14px;
  border: 1px solid rgba(245, 200, 76, 0.18);
  border-radius: 12px;
  color: var(--gold);
  background: rgba(245, 200, 76, 0.06);
  font-weight: 850;
  line-height: 1.45;
}

.mission-flow-panel,
.mission-blueprint-preview {
  padding: clamp(16px, 2vw, 22px);
}

.mission-flow-steps,
.mission-blueprint-grid,
.mission-memory-metrics,
.mission-decision-list {
  display: grid;
  gap: 10px;
}

.mission-flow-steps {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  margin-top: 16px;
}

.mission-flow-steps a {
  min-width: 0;
  padding: 13px;
  border: 1px solid rgba(245, 200, 76, 0.16);
  border-radius: 12px;
  color: inherit;
  text-decoration: none;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.052), rgba(255, 255, 255, 0.018)),
    rgba(8, 12, 18, 0.72);
}

.mission-flow-steps span {
  display: inline-flex;
  margin-bottom: 9px;
  color: var(--gold);
  font-size: 11px;
  font-weight: 900;
}

.mission-flow-steps strong,
.mission-decision-list strong,
.mission-section-card strong,
.mission-memory-metrics strong {
  display: block;
  color: var(--text-main);
  line-height: 1.22;
}

.mission-flow-steps p {
  margin: 8px 0 0;
  color: var(--text-muted);
  font-size: 12px;
  line-height: 1.45;
}

.mission-decision-list {
  margin: 16px 0;
}

.mission-decision-list a {
  min-width: 0;
  padding: 12px 13px;
  border: 1px solid var(--border-soft);
  border-radius: 12px;
  color: inherit;
  text-decoration: none;
  background: rgba(255, 255, 255, 0.04);
}

.mission-decision-list span,
.mission-decision-list em {
  display: block;
  margin-top: 5px;
  color: var(--text-muted);
  font-size: 11.5px;
  font-style: normal;
  font-weight: 760;
  line-height: 1.35;
}

.mission-decision-list em {
  color: var(--gold);
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.mission-memory-metrics {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: 16px 0;
}

.mission-memory-metrics span {
  min-width: 0;
  padding: 13px;
  border: 1px solid rgba(56, 214, 255, 0.16);
  border-radius: 12px;
  background: rgba(56, 214, 255, 0.045);
}

.mission-memory-metrics em,
.mission-memory-metrics small,
.mission-section-card em,
.mission-section-card small,
.mission-section-card p {
  display: block;
  color: var(--text-muted);
  font-style: normal;
  font-weight: 760;
  line-height: 1.35;
}

.mission-memory-metrics em {
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mission-memory-metrics strong {
  margin: 7px 0;
  color: var(--gold);
  font-size: 24px;
}

.mission-blueprint-grid {
  grid-template-columns: repeat(5, minmax(0, 1fr));
  margin-top: 16px;
}

.mission-blueprint-group {
  min-width: 0;
}

.mission-blueprint-group h4 {
  margin: 0 0 10px;
  color: var(--gold);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.mission-blueprint-group > div {
  display: grid;
  gap: 8px;
}

.mission-section-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 7px 9px;
  min-width: 0;
  min-height: 112px;
  padding: 11px;
  border: 1px solid var(--border-soft);
  border-radius: 10px;
  color: inherit;
  text-decoration: none;
  background: rgba(255, 255, 255, 0.035);
}

.mission-section-card span {
  color: var(--gold);
  font-size: 12px;
  font-weight: 950;
}

.mission-section-card em {
  justify-self: end;
  padding: 3px 6px;
  border: 1px solid rgba(245, 200, 76, 0.15);
  border-radius: 999px;
  color: var(--text-body);
  background: rgba(245, 200, 76, 0.04);
  font-size: 8.5px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.mission-section-card small,
.mission-section-card p {
  grid-column: 1 / -1;
  overflow-wrap: anywhere;
  font-size: 11px;
}

.mission-section-card p {
  margin: 0;
}

.market-regime-card,
.signal-board-card {
  background:
    radial-gradient(circle at 88% 0%, rgba(56, 214, 255, 0.15), transparent 40%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.074), rgba(255, 255, 255, 0.026));
}

.risk-desk-card {
  background:
    radial-gradient(circle at 0% 0%, rgba(255, 81, 81, 0.10), transparent 34%),
    rgba(10, 12, 17, 0.88);
}

.regime-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin: 16px 0;
}

.regime-tile {
  min-width: 0;
  padding: 13px;
  border: 1px solid var(--border-soft);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
}

.regime-tile strong,
.mission-alert-strip strong,
.mission-list-grid strong,
.mission-signal-list strong,
.source-feed-list strong,
.mission-queue-list strong {
  display: block;
  color: var(--text-main);
  font-size: 15px;
  line-height: 1.2;
}

.regime-tile span,
.regime-tile small,
.mission-alert-strip span,
.mission-alert-strip em,
.mission-list-grid span,
.mission-list-grid em,
.source-feed-list span,
.source-feed-list em,
.mission-queue-list span,
.mission-queue-list em {
  display: block;
  margin-top: 5px;
  color: var(--text-muted);
  font-size: 11.5px;
  font-style: normal;
  font-weight: 750;
  line-height: 1.35;
  text-transform: uppercase;
}

.regime-tile em {
  display: inline-flex;
  margin-top: 10px;
  color: var(--cyan);
  font-size: 11px;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mission-footnote {
  color: var(--text-muted) !important;
  font-size: 12.5px !important;
}

.mission-main-grid {
  display: grid;
  grid-template-columns: minmax(320px, 0.82fr) minmax(0, 1.18fr);
  gap: 18px;
}

.mission-alert-strip,
.mission-list-grid,
.source-feed-list,
.mission-queue-list {
  display: grid;
  gap: 10px;
  margin: 16px 0;
}

.mission-alert-strip a,
.mission-list-grid a,
.source-feed-list a,
.mission-queue-list a {
  min-width: 0;
  padding: 13px;
  border: 1px solid var(--border-soft);
  border-radius: 12px;
  color: inherit;
  text-decoration: none;
  background: rgba(255, 255, 255, 0.04);
  transition: border-color 0.18s ease, background 0.18s ease, transform 0.18s ease;
}

.mission-alert-strip a:hover,
.mission-list-grid a:hover,
.source-feed-list a:hover,
.mission-queue-list a:hover {
  border-color: rgba(245, 200, 76, 0.28);
  background: rgba(245, 200, 76, 0.06);
  transform: translateY(-1px);
}

.mission-agent-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 16px 0;
}

.mission-agent-card {
  position: relative;
  min-width: 0;
  min-height: 164px;
  padding: 14px;
  border: 1px solid rgba(56, 214, 255, 0.15);
  border-radius: 13px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.056), rgba(255, 255, 255, 0.022)),
    rgba(7, 12, 18, 0.78);
}

.mission-agent-card .agent-state-dot {
  position: absolute;
  right: 14px;
  top: 14px;
  width: 8px;
  height: 8px;
}

.mission-agent-card strong {
  display: block;
  color: var(--gold);
  font-size: 16px;
}

.mission-agent-card em,
.mission-agent-card small {
  display: block;
  margin-top: 5px;
  color: var(--cyan);
  font-size: 11px;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mission-agent-card p {
  margin: 10px 0;
  color: var(--text-body);
  font-size: 12.5px;
  line-height: 1.5;
}

.watchlist-pulse-card {
  background:
    radial-gradient(circle at 100% 0%, rgba(73, 242, 143, 0.13), transparent 36%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.074), rgba(255, 255, 255, 0.026));
}

.mission-signal-list {
  display: grid;
  gap: 10px;
  margin: 16px 0;
}

.mission-signal-list article {
  padding: 13px;
  border: 1px solid var(--border-soft);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.04);
}

.mission-signal-list span,
.mission-signal-list small,
.mission-signal-list em {
  display: inline-flex;
  margin: 8px 8px 0 0;
  color: var(--text-muted);
  font-size: 11px;
  font-style: normal;
  font-weight: 850;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.mission-signal-list p {
  margin: 10px 0 0;
  color: var(--text-body);
  font-size: 12.5px;
  line-height: 1.45;
}

.private-memory-card {
  background:
    radial-gradient(circle at 90% 0%, rgba(167, 139, 250, 0.13), transparent 38%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.074), rgba(255, 255, 255, 0.026));
}

.mission-terminal-band {
  display: grid;
  grid-template-columns: minmax(140px, auto) minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 14px 16px;
  border: 1px solid rgba(245, 200, 76, 0.2);
  border-radius: 14px;
  background: rgba(4, 7, 11, 0.88);
  color: var(--text-body);
}

.mission-terminal-band span,
.mission-terminal-band strong,
.mission-terminal-band a {
  min-width: 0;
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.mission-terminal-band span {
  color: var(--gold);
}

.mission-terminal-band strong {
  color: var(--text-muted);
}

.mission-terminal-band a {
  justify-self: end;
  color: var(--cyan);
  text-decoration: none;
}

@media (max-width: 1180px) {
  .mission-hero,
  .mission-main-grid {
    grid-template-columns: 1fr;
  }

  .mission-stat-grid,
  .regime-grid,
  .mission-flow-steps,
  .mission-blueprint-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .mission-agent-grid,
  .mission-memory-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .mission-hero {
    padding: 18px;
  }

  .mission-stat-grid,
  .regime-grid,
  .mission-agent-grid,
  .mission-flow-steps,
  .mission-blueprint-grid,
  .mission-memory-metrics {
    grid-template-columns: 1fr;
  }

  .mission-terminal-band {
    grid-template-columns: 1fr;
  }

  .mission-terminal-band a {
    justify-self: start;
  }
}

/* Phase 2B Watchlists prototype */
.watchlists-shell {
  display: grid;
  gap: 20px;
}

.watchlist-command-grid {
  display: grid;
  grid-template-columns: minmax(300px, 0.96fr) minmax(430px, 1.24fr) minmax(310px, 0.9fr);
  gap: 20px;
  align-items: stretch;
}

.watchlist-command-card {
  background:
    radial-gradient(circle at 12% 0%, rgba(245, 200, 76, 0.18), transparent 42%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.084), rgba(255, 255, 255, 0.03));
}

.watchlist-priority-card {
  background:
    radial-gradient(circle at 86% 8%, rgba(163, 230, 53, 0.14), transparent 38%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.074), rgba(255, 255, 255, 0.026));
}

.watchlist-priority-list,
.watchlist-agent-list,
.watchlist-review-list {
  display: grid;
  gap: 10px;
  margin-top: 14px;
}

.watchlist-priority-row,
.watchlist-agent-list span {
  display: grid;
  grid-template-columns: 72px minmax(0, 1fr) minmax(118px, auto);
  gap: 12px;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid var(--border-soft);
}

.watchlist-priority-row strong,
.watchlist-asset-row strong,
.watchlist-review-list article > strong {
  color: var(--text-main);
  font-size: 18px;
  font-weight: 900;
  letter-spacing: 0.02em;
}

.watchlist-priority-row span,
.watchlist-asset-row span,
.watchlist-review-list article > span {
  color: var(--text-body);
  font-size: 14.5px;
  line-height: 1.35;
}

.watchlist-priority-row em,
.watchlist-asset-row em,
.watchlist-review-list article > em,
.watchlist-agent-list em {
  justify-self: end;
  color: var(--gold);
  font-size: 12px;
  font-style: normal;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.watchlist-truth-card {
  min-width: 0;
}

.watchlist-universe-card {
  overflow: hidden;
}

.watchlist-asset-list {
  display: grid;
  gap: 10px;
  margin-top: 16px;
  max-height: 620px;
  overflow: auto;
  padding-right: 6px;
}

.watchlist-asset-row {
  display: grid;
  grid-template-columns: 86px minmax(180px, 1.2fr) minmax(160px, 0.95fr) minmax(128px, 0.72fr) minmax(148px, 0.8fr);
  gap: 12px;
  align-items: center;
  padding: 14px;
  border: 1px solid var(--border-soft);
  border-radius: 14px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.058), rgba(255, 255, 255, 0.026)),
    rgba(12, 17, 24, 0.72);
}

.watchlist-asset-row:hover {
  border-color: rgba(163, 230, 53, 0.22);
  transform: translateY(-1px);
}

.watchlist-asset-row small {
  grid-column: 2 / -1;
  color: var(--text-muted);
  font-size: 12.5px;
  line-height: 1.45;
}

.watchlist-bucket-grid,
.watchlist-lower-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.watchlist-bucket-card {
  display: grid;
  gap: 12px;
  background:
    radial-gradient(circle at 100% 0%, rgba(56, 214, 255, 0.11), transparent 36%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.07), rgba(255, 255, 255, 0.025));
}

.watchlist-lower-grid {
  grid-template-columns: minmax(300px, 0.82fr) minmax(0, 1.18fr);
}

.watchlist-agent-list span {
  grid-template-columns: minmax(130px, 0.72fr) minmax(0, 1fr);
}

.watchlist-agent-list strong {
  color: var(--text-main);
  font-size: 14.5px;
}

.watchlist-review-list article {
  display: grid;
  grid-template-columns: 82px minmax(0, 1fr) minmax(120px, auto);
  gap: 12px;
  align-items: center;
  padding: 14px;
  border: 1px solid var(--border-soft);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.04);
}

.watchlist-review-list article .action-row {
  grid-column: 1 / -1;
  margin-top: 2px;
}

.watchlist-workflow-card,
.watchlist-future-state {
  overflow: hidden;
}

.watchlist-workflow {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 16px;
}

.watchlist-workflow span {
  position: relative;
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  padding: 9px 14px;
  border: 1px solid rgba(245, 200, 76, 0.18);
  border-radius: 999px;
  color: var(--text-body);
  background: rgba(245, 200, 76, 0.06);
  font-size: 13px;
  font-weight: 850;
}

.watchlist-workflow span:not(:last-child)::after {
  content: ">";
  margin-left: 12px;
  color: rgba(245, 200, 76, 0.7);
}

@media (max-width: 1280px) {
  .watchlist-command-grid,
  .watchlist-bucket-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .watchlist-truth-card {
    grid-column: 1 / -1;
  }

  .watchlist-asset-row {
    grid-template-columns: 78px minmax(180px, 1fr) minmax(150px, 0.8fr);
  }

  .watchlist-asset-row em,
  .watchlist-asset-row small {
    grid-column: 2 / -1;
    justify-self: start;
  }
}

@media (max-width: 860px) {
  .watchlist-command-grid,
  .watchlist-bucket-grid,
  .watchlist-lower-grid {
    grid-template-columns: 1fr;
  }

  .watchlist-priority-row,
  .watchlist-agent-list span,
  .watchlist-review-list article {
    grid-template-columns: 1fr;
    gap: 5px;
  }

  .watchlist-priority-row em,
  .watchlist-agent-list em,
  .watchlist-review-list article > em {
    justify-self: start;
  }

  .watchlist-asset-list {
    max-height: none;
    padding-right: 0;
  }

  .watchlist-asset-row {
    grid-template-columns: 1fr;
    gap: 6px;
  }

  .watchlist-asset-row em,
  .watchlist-asset-row small {
    grid-column: auto;
  }

  .watchlist-workflow {
    display: grid;
  }

  .watchlist-workflow span {
    justify-content: center;
    border-radius: 12px;
    text-align: center;
  }

  .watchlist-workflow span:not(:last-child)::after {
    content: "";
    display: none;
  }
}

/* Phase 1.6 premium polish layer */
:root {
  --sidebar-width: 334px;
  --radius: 11px;
  --font-base: 14.5px;
  --font-small: 12px;
  --surface-1: #121923;
  --surface-2: #17202b;
  --surface-3: #1d2835;
  --border-soft: rgba(255, 255, 255, 0.105);
  --border-mid: rgba(255, 255, 255, 0.17);
  --text-body: #d3dbe6;
  --text-muted: #9aa7b8;
  --text-faint: #708196;
}

body {
  font-size: var(--font-base);
  line-height: 1.55;
  background:
    radial-gradient(circle at 10% 0%, rgba(56, 214, 255, 0.105), transparent 30%),
    radial-gradient(circle at 86% 12%, rgba(245, 200, 76, 0.08), transparent 25%),
    radial-gradient(circle at 55% 100%, rgba(169, 112, 255, 0.065), transparent 34%),
    linear-gradient(180deg, #080b10 0%, #07090d 58%, #05070a 100%);
}

.rail {
  padding: 20px 18px;
  background:
    linear-gradient(180deg, rgba(12, 17, 24, 0.96), rgba(7, 9, 13, 0.94)),
    var(--bg-main);
  box-shadow: inset -1px 0 0 rgba(255, 255, 255, 0.03), 18px 0 50px rgba(0, 0, 0, 0.18);
}

.brand {
  padding: 16px;
  gap: 12px;
  border-radius: 16px;
  border-color: rgba(245, 200, 76, 0.16);
  background:
    radial-gradient(circle at 18% 10%, rgba(245, 200, 76, 0.11), transparent 36%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.064), rgba(255, 255, 255, 0.024));
}

.brand strong {
  font-size: 15px;
}

.brand small {
  font-size: 11.5px;
  letter-spacing: 0.08em;
}

.nav.sidebar-shell {
  gap: 21px;
  margin: 26px 0;
}

.sidebar-group {
  gap: 7px;
}

.sidebar-group-label {
  padding: 0 7px 3px;
  color: #98a8ba;
  font-size: 11px;
  letter-spacing: 0.14em;
}

.nav-button.sidebar-item {
  min-height: 56px;
  grid-template-columns: 76px minmax(0, 1fr);
  gap: 12px;
  padding: 10px 11px;
  border-radius: 12px;
  color: #dbe4f0;
  font-size: 14.5px;
  line-height: 1.18;
}

.nav-button.sidebar-item .sidebar-code {
  width: 76px;
  height: 34px;
  border-radius: 10px;
  font-size: 10.5px;
  font-weight: 850;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--route-accent) 14%, transparent), rgba(255, 255, 255, 0.025));
}

.sidebar-copy {
  gap: 3px;
}

.sidebar-copy strong {
  font-size: 14.5px;
  font-weight: 740;
  letter-spacing: 0;
}

.sidebar-status {
  color: #8494a8;
  font-size: 12px;
}

.nav-button.sidebar-item:hover {
  background: color-mix(in srgb, var(--route-accent) 8%, rgba(255, 255, 255, 0.035));
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.18);
}

.nav-button.sidebar-item.active {
  border-color: color-mix(in srgb, var(--route-accent) 62%, transparent);
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--route-accent) 20%, transparent), rgba(255, 255, 255, 0.04));
  box-shadow:
    inset 4px 0 0 var(--route-accent),
    0 0 0 1px color-mix(in srgb, var(--route-accent) 16%, transparent),
    0 14px 34px rgba(0, 0, 0, 0.22);
}

.topbar {
  padding: 17px clamp(20px, 2vw, 34px);
}

.topbar h1 {
  font-size: 22px;
}

.page-shell {
  width: min(100%, 1740px);
  margin: 0 auto;
  padding: clamp(24px, 2.55vw, 44px);
}

.page-hero {
  gap: 28px;
  margin-bottom: 24px;
  padding-bottom: 24px;
}

.page-kicker,
.eyebrow {
  font-size: 11.5px;
  letter-spacing: 0.15em;
}

.page-title {
  font-size: clamp(38px, 4.7vw, 72px);
  line-height: 0.96;
  font-weight: 790;
}

.page-subtitle {
  max-width: 860px;
  font-size: clamp(15px, 1.1vw, 17px);
  line-height: 1.68;
  color: #aebaca;
}

.split-layout {
  gap: 20px;
  grid-template-columns: minmax(270px, 0.9fr) minmax(390px, 1.42fr) minmax(300px, 0.92fr);
}

.section-grid {
  gap: 18px;
}

.glass-card,
.command-card,
.truth-panel,
.metric-card {
  border-radius: 14px;
  border-color: var(--border-soft);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.074), rgba(255, 255, 255, 0.026)),
    linear-gradient(135deg, rgba(56, 214, 255, 0.025), transparent 42%);
  box-shadow:
    0 22px 55px rgba(0, 0, 0, 0.30),
    inset 0 1px 0 rgba(255, 255, 255, 0.045);
}

.glass-card,
.command-card,
.truth-panel {
  padding: clamp(20px, 1.85vw, 28px);
}

.command-card {
  border-color: rgba(245, 200, 76, 0.22);
  background:
    radial-gradient(circle at 18% 0%, rgba(245, 200, 76, 0.11), transparent 38%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.075), rgba(255, 255, 255, 0.028));
}

.truth-panel {
  border-color: rgba(255, 184, 77, 0.22);
  background:
    radial-gradient(circle at 85% 0%, rgba(255, 93, 77, 0.085), transparent 36%),
    linear-gradient(180deg, rgba(255, 184, 77, 0.07), rgba(255, 255, 255, 0.026));
}

.glass-card:hover,
.command-card:hover,
.truth-panel:hover,
.metric-card:hover {
  transform: translateY(-2px);
  border-color: var(--border-mid);
  box-shadow:
    0 26px 68px rgba(0, 0, 0, 0.36),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.glass-card h3,
.command-card h3,
.truth-panel h3 {
  margin: 7px 0 9px;
  color: #f7f9fd;
  font-size: clamp(18px, 1.4vw, 24px);
  line-height: 1.16;
  font-weight: 760;
}

.glass-card p,
.command-card p,
.truth-panel p {
  color: #b8c4d2;
  font-size: 14.5px;
  line-height: 1.65;
}

.metric-card {
  padding: 16px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.064), rgba(255, 255, 255, 0.024));
}

.metric-card span,
.meta-label {
  color: #8292a6;
  font-size: 11px;
}

.metric-card strong {
  margin-top: 7px;
  font-size: clamp(20px, 1.55vw, 28px);
  line-height: 1.05;
}

.status-chip,
.safe-chip,
.review-chip,
.danger-chip {
  min-height: 32px;
  padding: 7px 12px;
  font-size: 12px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.045);
}

.primary-action,
.secondary-action {
  min-height: 42px;
  border-radius: 11px;
  padding: 10px 15px;
  font-size: 14px;
  transition: transform 0.18s ease, border-color 0.18s ease, background 0.18s ease, box-shadow 0.18s ease;
}

.primary-action {
  background: linear-gradient(180deg, #ffe184, var(--gold));
  color: #161206;
  box-shadow: 0 12px 30px rgba(245, 200, 76, 0.18);
}

.secondary-action {
  color: #dce5f0;
  background: rgba(255, 255, 255, 0.052);
}

.primary-action:hover,
.secondary-action:hover,
.primary-action:focus-visible,
.secondary-action:focus-visible {
  outline: 0;
  transform: translateY(-2px);
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.28);
}

.pc-list li {
  padding: 11px 0;
  align-items: center;
}

.pc-list strong {
  color: #f5f8fd;
  text-align: right;
}

#alerts .command-card > .section-grid,
#alerts .glass-card > .section-grid {
  gap: 12px;
}

#alerts .action-row {
  gap: 9px;
}

#alerts .truth-list span {
  padding: 10px 0;
  font-size: 13.5px;
}

#alerts .truth-list strong {
  color: #f8d26a;
}

.agent-network {
  min-height: clamp(620px, 64vh, 780px);
  border-radius: 18px;
  border-color: rgba(255, 255, 255, 0.13);
  background:
    radial-gradient(circle at 50% 48%, rgba(245, 200, 76, 0.20), transparent 19%),
    radial-gradient(circle at 21% 24%, rgba(56, 214, 255, 0.16), transparent 24%),
    radial-gradient(circle at 79% 73%, rgba(169, 112, 255, 0.13), transparent 25%),
    linear-gradient(180deg, rgba(20, 29, 41, 0.94), rgba(8, 12, 18, 0.98));
  box-shadow:
    0 34px 90px rgba(0, 0, 0, 0.36),
    inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.agent-network::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.035), transparent 24%, rgba(0, 0, 0, 0.12));
}

.agent-path {
  stroke: rgba(151, 169, 190, 0.42);
  stroke-width: 0.58;
}

.agent-path.active {
  stroke: rgba(92, 218, 255, 0.72);
  stroke-dasharray: 5 9;
  animation-duration: 12s;
}

.data-pulse {
  width: 8px;
  height: 8px;
  animation-duration: 9.5s;
}

.agent-node {
  width: clamp(130px, 12vw, 168px);
  min-height: 84px;
  padding: 13px;
  border-radius: 14px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--node-accent, var(--cyan)) 10%, rgba(10, 15, 22, 0.9)), rgba(8, 12, 18, 0.88));
  box-shadow:
    0 18px 46px rgba(0, 0, 0, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.agent-node.core {
  width: clamp(178px, 17vw, 246px);
  min-height: 122px;
  box-shadow:
    0 0 0 1px rgba(245, 200, 76, 0.26),
    0 28px 74px rgba(245, 200, 76, 0.10),
    0 28px 74px rgba(0, 0, 0, 0.38);
}

.agent-node strong {
  font-size: 14.5px;
}

.agent-node small {
  color: #a8b5c4;
  font-size: 12px;
}

.agent-node:hover,
.agent-node:focus-visible {
  transform: translate(-50%, -54%) scale(1.015);
  box-shadow:
    0 0 0 1px color-mix(in srgb, var(--node-accent, var(--cyan)) 42%, transparent),
    0 24px 64px rgba(0, 0, 0, 0.38);
}

.agent-tooltip {
  width: min(300px, 76vw);
  border-radius: 13px;
  padding: 14px;
  font-size: 12.5px;
  line-height: 1.55;
  background: rgba(9, 13, 19, 0.98);
}

.agent-status-rail {
  position: absolute;
  left: 22px;
  right: 22px;
  bottom: 20px;
  z-index: 3;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.agent-status-rail article {
  border: 1px solid rgba(255, 255, 255, 0.105);
  border-radius: 12px;
  padding: 12px;
  background: rgba(7, 10, 15, 0.72);
  backdrop-filter: blur(14px);
}

.agent-status-rail span {
  color: #8494a8;
  display: block;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.agent-status-rail strong {
  color: #f5f8fd;
  display: block;
  font-size: 15px;
  margin-top: 4px;
}

@media (min-width: 1500px) {
  .split-layout {
    grid-template-columns: minmax(330px, 0.92fr) minmax(560px, 1.5fr) minmax(340px, 0.95fr);
  }
}

@media (max-width: 1060px) {
  :root {
    --sidebar-width: 100%;
  }

  .rail {
    padding: 16px;
  }

  .nav.sidebar-shell {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .nav-button.sidebar-item {
    min-height: 54px;
  }
}

@media (max-width: 760px) {
  body {
    font-size: 14px;
  }

  .page-shell {
    padding: 18px;
  }

  .page-title {
    font-size: clamp(34px, 13vw, 48px);
  }

  .page-hero {
    gap: 16px;
  }

  .nav.sidebar-shell {
    gap: 14px;
  }

  .nav-button.sidebar-item {
    grid-template-columns: 72px minmax(0, 1fr);
  }

  .agent-status-rail {
    position: relative;
    left: auto;
    right: auto;
    bottom: auto;
    grid-template-columns: 1fr;
    margin-top: 6px;
  }

  .agent-node,
  .agent-node.core {
    width: 100%;
    min-height: auto;
  }
}

@media (prefers-reduced-motion: reduce) {
  .glass-card:hover,
  .command-card:hover,
  .truth-panel:hover,
  .metric-card:hover,
  .primary-action:hover,
  .secondary-action:hover,
  .agent-node:hover,
  .agent-node:focus-visible {
    transform: none !important;
  }
}

@keyframes habitatScan {
  from { transform: translateX(-65%); }
  to { transform: translateX(65%); }
}

@keyframes unitBob {
  0%, 100% { margin-top: 0; }
  50% { margin-top: -8px; }
}

@media (max-width: 1280px) {
