    --sidebar-width: 290px;
  }

  .strategic-hub-layout,
  .habitat-shell,
  .vault-layout,
  .jarvis-hero,
  .lifeos-hero,
  .agent-civilization-grid,
  .home-alerts-only,
  .alerts-command-layout,
  .world-hero,
  .world-layout,
  .world-dashboard,
  .agent-command-deck,
  .agent-ecosystem-console,
  .agent-task-board,
  .bottom-ops-panels,
  .home-command-hero,
  .home-alert-hero,
  .completion-head,
  .tracker-editor-grid,
  .vision-detail-layout,
  .vision-habitat-band,
  .agent-os-grid,
  .tracker-layout,
  .selected-signal-detail {
    grid-template-columns: 1fr;
  }

  .vision-dashboard-panels {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .home-alert-grid,
  .home-command-links,
  .game-routine-bar,
  .world-hierarchy,
  .world-agent-card-row,
  .vault-grid,
  .jarvis-card-grid,
  .lifeos-module-grid,
  .bookmark-preview-list,
  .duplicate-grid,
  .integration-card-grid,
  .ceob-briefing-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .bottom-ops-panels {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .signal-workbench {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 1540px) {
  :root {
    --sidebar-width: 300px;
  }

  .strategic-hub-layout,
  .habitat-shell {
    grid-template-columns: 1fr;
  }

  .strategic-command-map,
  .agent-city {
    min-width: 0;
  }

  .agent-civilization-map {
    min-width: 0;
  }
}

@media (max-width: 820px) {
  :root {
    --page-padding: 14px;
    --font-base: 16px;
  }

  .vision-dashboard-panels,
  .bottom-ops-panels,
  .alerts-command-layout,
  .alert-exact-trade,
  .home-alerts-only,
  .world-hero,
  .world-layout,
  .world-dashboard,
  .world-progress-board,
  .world-score-grid,
  .world-hierarchy,
  .world-agent-card-row,
  .world-detail-grid,
  .vault-metrics,
  .vault-grid,
  .jarvis-card-grid,
  .lifeos-module-grid,
  .bookmark-preview-list,
  .duplicate-grid,
  .integration-card-grid,
  .roadmap-steps,
  .lifeos-flow,
  .recovery-grid,
  .ceob-briefing-grid,
  .jarvis-stat-grid,
  .device-role-row,
  .tracker-edit-row,
  .metric-strip,
  .signal-workbench,
  .archive-actions {
    grid-template-columns: 1fr !important;
  }

  .world-map {
    min-height: 980px;
  }

  .world-ceo,
  .world-floor,
  .world-habitat {
    width: 82%;
    left: 50% !important;
    transform: translateX(-50%);
  }

  .world-ceo { top: 24px; }
  .world-floor { top: 190px; transform: translateX(-50%); border-radius: 24px; }
  .world-habitat.market { top: 350px !important; }
