/* Scrollbars */
::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
::-webkit-scrollbar-track {
  background: #0c0d0e;
}
::-webkit-scrollbar-thumb {
  background: #232529;
}
::-webkit-scrollbar-thumb:hover {
  background: #3a3d45;
}

/* Animations */
@keyframes glowing-route-dash {
  to {
    stroke-dashoffset: -40;
  }
}
.glowing-route {
  stroke-dasharray: 8 4;
  animation: glowing-route-dash 2s linear infinite;
}

@keyframes pulse-dot {
  0% {
    transform: scale(0.8);
    opacity: 0.5;
  }
  50% {
    transform: scale(1.2);
    opacity: 1;
  }
  100% {
    transform: scale(0.8);
    opacity: 0.5;
  }
}
.status-pulse-dot {
  animation: pulse-dot 2s infinite ease-in-out;
}

@keyframes scanline {
  0% {
    transform: translateY(-100%);
  }
  100% {
    transform: translateY(100%);
  }
}
.scanline-effect::after {
  content: " ";
  display: block;
  position: absolute;
  top: 0; left: 0; bottom: 0; right: 0;
  background: linear-gradient(rgba(18, 16, 16, 0) 50%, rgba(0, 0, 0, 0.25) 50%), linear-gradient(90deg, rgba(255, 0, 0, 0.06), rgba(0, 255, 0, 0.02), rgba(0, 0, 255, 0.06));
  z-index: 2;
  background-size: 100% 2px, 3px 100%;
  pointer-events: none;
}

