  background:
    radial-gradient(circle at 50% 47%, rgba(245, 200, 76, 0.13), transparent 20%),
    radial-gradient(circle at 22% 24%, rgba(56, 214, 255, 0.1), transparent 19%),
    radial-gradient(circle at 76% 74%, rgba(169, 112, 255, 0.09), transparent 21%),
    linear-gradient(180deg, rgba(17, 24, 33, 0.88), rgba(8, 12, 18, 0.94));
}

.agent-network::before {
  content: "";
  position: absolute;
  inset: 18px;
  border: 1px solid rgba(255, 255, 255, 0.035);
  border-radius: 50%;
}

.agent-paths {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
}

.agent-path {
  fill: none;
  stroke: rgba(140, 153, 170, 0.34);
  stroke-width: 0.45;
  vector-effect: non-scaling-stroke;
}

.agent-path.active {
  stroke: rgba(56, 214, 255, 0.62);
  stroke-dasharray: 4 7;
  animation: pathDrift 8s linear infinite;
}

.agent-node {
  position: absolute;
  left: var(--x);
  top: var(--y);
  transform: translate(-50%, -50%);
  z-index: 2;
  width: clamp(112px, 11vw, 148px);
  min-height: 72px;
  display: grid;
  gap: 3px;
  align-content: center;
  padding: 11px;
  border: 1px solid color-mix(in srgb, var(--node-accent, var(--cyan)) 48%, transparent);
  border-radius: 10px;
  background: rgba(8, 12, 18, 0.82);
  color: var(--text-main);
  text-align: left;
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.25);
}

.agent-node:hover,
.agent-node:focus-visible {
  outline: 0;
  border-color: var(--node-accent, var(--cyan));
  background: color-mix(in srgb, var(--node-accent, var(--cyan)) 11%, rgba(8, 12, 18, 0.88));
  transform: translate(-50%, -52%);
}

.agent-node.core {
  width: clamp(150px, 16vw, 210px);
  min-height: 104px;
  border-color: rgba(245, 200, 76, 0.62);
  background: linear-gradient(180deg, rgba(245, 200, 76, 0.14), rgba(10, 13, 18, 0.92));
}

.agent-node strong {
  font-size: 13px;
  line-height: 1.1;
}

.agent-node small {
  color: var(--text-muted);
  font-size: 11px;
  line-height: 1.25;
}

.agent-tooltip {
  position: absolute;
  left: 50%;
  top: calc(100% + 10px);
  width: min(260px, 72vw);
  transform: translateX(-50%);
  opacity: 0;
  pointer-events: none;
  border: 1px solid var(--border-mid);
  border-radius: 8px;
  padding: 11px;
  background: rgba(7, 9, 13, 0.96);
  color: var(--text-body);
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.38);
}

.agent-node:hover .agent-tooltip,
.agent-node:focus-visible .agent-tooltip {
  opacity: 1;
}

.data-pulse {
  position: absolute;
  left: var(--sx);
  top: var(--sy);
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--cyan);
  box-shadow: 0 0 18px rgba(56, 214, 255, 0.65);
  animation: packetMove 7.5s linear infinite;
  animation-delay: var(--delay, 0s);
}

.truth-list {
  display: grid;
  gap: 8px;
}

.truth-list span {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  border-bottom: 1px solid var(--border-soft);
  padding-bottom: 8px;
}

.truth-list span:last-child {
  border-bottom: 0;
}

.mini-flow {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  color: var(--text-muted);
}

.mini-flow span {
  border: 1px solid var(--border-soft);
  border-radius: 999px;
  padding: 6px 9px;
  background: rgba(255, 255, 255, 0.026);
}

@keyframes pathDrift {
  from { stroke-dashoffset: 0; }
  to { stroke-dashoffset: -44; }
}

@keyframes packetMove {
  from { transform: translate(0, 0); opacity: 0; }
  12% { opacity: 1; }
  82% { opacity: 1; }
  to { transform: translate(var(--tx), var(--ty)); opacity: 0; }
}

@media (max-width: 1060px) {
  .nav.sidebar-shell {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
  }

  .split-layout,
  .page-hero {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 760px) {
  .page-shell {
    padding: 16px;
  }

  .section-grid {
    grid-template-columns: 1fr;
  }

  .nav.sidebar-shell {
    grid-template-columns: 1fr;
  }

  .agent-network {
    min-height: auto;
    display: grid;
    gap: 10px;
    padding: 14px;
  }

  .agent-paths,
  .data-pulse,
  .agent-network::before {
    display: none;
  }

  .agent-node,
  .agent-node.core {
    position: relative;
    left: auto;
    top: auto;
    transform: none;
    width: 100%;
  }

  .agent-node:hover,
  .agent-node:focus-visible {
    transform: none;
  }

  .agent-tooltip {
    position: static;
    width: auto;
    transform: none;
    opacity: 1;
    margin-top: 8px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

