/* Phase 2P Staging declutter. */
#staging.active .staging-qa-shell {
  display: grid;
  gap: 12px !important;
  max-width: 1480px;
  padding: 16px !important;
}

#staging.active .staging-qa-shell .page-hero {
  min-height: 0 !important;
  grid-template-columns: minmax(0, 1fr) auto !important;
  align-items: end !important;
  gap: 16px !important;
  margin: 0 !important;
  padding: 16px !important;
  border-radius: 8px !important;
  background: #111722 !important;
  color: #c8d2df !important;
}

#staging.active .staging-qa-shell .page-hero h2 {
  margin: 2px 0 6px !important;
  color: #f0f5fb !important;
  font-size: clamp(30px, 3vw, 46px) !important;
  line-height: 1 !important;
}

#staging.active .staging-qa-shell .page-hero p,
#staging.active .staging-qa-shell .page-subtitle {
  max-width: 760px !important;
  color: #9aa7b8 !important;
  font-size: 14px !important;
  line-height: 1.45 !important;
}

#staging.active .staging-qa-shell .page-hero::before {
  display: none !important;
}

#staging.active .staging-purpose-line,
#staging.active .staging-command-panel,
#staging.active .staging-lock-board,
#staging.active .staging-route-board,
#staging.active .staging-quiet-band,
#staging.active .staging-forbidden-work,
#staging.active .staging-quiet-details {
  min-width: 0;
  border: 1px solid rgba(170, 190, 215, 0.14);
  border-radius: 8px;
  background: #111722;
  color: #c8d2df;
  box-shadow: none;
}

#staging.active .staging-purpose-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px 16px;
}

#staging.active .staging-purpose-line p,
#staging.active .staging-panel-note {
  margin: 0;
  color: #9aa7b8;
  line-height: 1.55;
}

#staging.active .staging-purpose-line strong {
  color: #f0f5fb;
}

#staging.active .staging-primary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
}

#staging.active .staging-command-panel {
  display: grid;
  align-content: start;
  gap: 12px;
  padding: 16px;
}

#staging.active .staging-command-panel h3 {
  margin: 0;
  color: #f0f5fb;
  font-size: 18px;
  line-height: 1.25;
}

#staging.active .staging-status-lock {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

#staging.active .staging-status-lock strong {
  color: #83d6a0;
  font-size: clamp(28px, 3vw, 42px);
  line-height: 0.9;
  letter-spacing: -0.04em;
}

#staging.active .staging-status-lock span {
  padding: 4px 8px;
  border: 1px solid rgba(131, 214, 160, 0.28);
  border-radius: 999px;
  color: #a7e8bc;
  background: rgba(64, 150, 94, 0.12);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

#staging.active .staging-key-values {
  display: grid;
  gap: 7px;
  margin: 0;
}

#staging.active .staging-key-values div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding-top: 7px;
  border-top: 1px solid rgba(170, 190, 215, 0.1);
}

#staging.active .staging-key-values dt {
  color: #8e9caf;
  font-size: 11px;
}

#staging.active .staging-key-values dd {
  margin: 0;
  color: #edf3fa;
  font-size: 11px;
  font-weight: 700;
  text-align: right;
}

#staging.active .staging-key-values code {
  color: #f5c84c;
}

#staging.active .staging-decision-panel {
  border-color: rgba(245, 200, 76, 0.28);
  background:
    linear-gradient(140deg, rgba(245, 200, 76, 0.08), transparent 54%),
    #111722;
}

#staging.active .staging-decision-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
}

#staging.active .staging-decision-actions a,
#staging.active .staging-tracker-panel > a {
  min-height: 44px;
}

#staging.active .staging-fact-list,
#staging.active .staging-approval-list {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

#staging.active .staging-fact-list li,
#staging.active .staging-route-matrix span,
#staging.active .staging-approval-list li,
#staging.active .staging-quiet-band span {
  min-width: 0;
  border: 1px solid rgba(170, 190, 215, 0.11);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.035);
}

#staging.active .staging-fact-list li {
  display: grid;
  gap: 3px;
  padding: 9px;
}

#staging.active .staging-fact-list span,
#staging.active .staging-route-matrix small {
  color: #8e9caf;
  font-size: 11px;
  line-height: 1.35;
}

#staging.active .staging-fact-list strong,
#staging.active .staging-route-matrix strong {
  color: #f0f5fb;
  font-size: 13px;
  line-height: 1.35;
}

#staging.active .staging-route-matrix {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

#staging.active .staging-route-matrix span {
  display: grid;
  grid-template-columns: minmax(108px, 0.75fr) auto;
  gap: 3px 8px;
  padding: 8px 9px;
}

#staging.active .staging-route-matrix em {
  justify-self: end;
  align-self: start;
  padding: 2px 6px;
  border: 1px solid rgba(245, 200, 76, 0.22);
  border-radius: 999px;
  color: #f5c84c;
  background: rgba(245, 200, 76, 0.07);
  font-size: 10px;
  font-style: normal;
  text-transform: uppercase;
}

#staging.active .staging-route-matrix em.is-local {
  border-color: rgba(143, 165, 194, 0.24);
  color: #b5c5d9;
  background: rgba(143, 165, 194, 0.08);
}

#staging.active .staging-route-matrix small {
  grid-column: 1 / -1;
}

#staging.active .staging-approval-list {
  counter-reset: staging-approval;
}

#staging.active .staging-approval-list li {
  position: relative;
  padding: 10px 10px 10px 36px;
  color: #f0f5fb;
  line-height: 1.35;
}

#staging.active .staging-approval-list li::before {
  counter-increment: staging-approval;
  content: counter(staging-approval);
  position: absolute;
  left: 10px;
  top: 9px;
  display: grid;
  place-items: center;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  color: #0b0d11;
  background: #f5c84c;
  font-size: 11px;
  font-weight: 800;
}

#staging.active .staging-quiet-band {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 12px;
}

#staging.active .staging-quiet-band span {
  padding: 6px 8px;
  color: #aab6c7;
  font-size: 11px;
  line-height: 1.3;
}

#staging.active .staging-lock-board,
#staging.active .staging-route-board,
#staging.active .staging-forbidden-work {
  display: grid;
  gap: 12px;
  padding: 16px;
}

#staging.active .staging-lock-board > header,
#staging.active .staging-route-board > header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 16px;
}

#staging.active .staging-lock-board h3,
#staging.active .staging-route-board h3,
#staging.active .staging-forbidden-work h3 {
  margin: 3px 0 0;
  color: #f0f5fb;
  font-size: 18px;
}

#staging.active .staging-lock-board > header > strong,
#staging.active .staging-route-board > header > strong {
  color: #83d6a0;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

#staging.active .staging-lock-board > div {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

#staging.active .staging-lock-board article {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 10px;
  border: 1px solid rgba(170, 190, 215, 0.11);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.035);
}

#staging.active .staging-lock-board article span {
  color: #8e9caf;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

#staging.active .staging-lock-board article strong {
  color: #a7e8bc;
  font-size: 12px;
}

#staging.active .staging-lock-board article small {
  color: #9aa7b8;
  font-size: 10px;
  line-height: 1.35;
}

#staging.active .staging-forbidden-work {
  grid-template-columns: minmax(180px, 0.32fr) minmax(0, 1fr);
  align-items: center;
  border-color: rgba(211, 99, 99, 0.2);
  background:
    linear-gradient(120deg, rgba(211, 99, 99, 0.06), transparent 42%),
    #111722;
}

#staging.active .staging-forbidden-work > div:last-child {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

#staging.active .staging-forbidden-work > div:last-child span {
  padding: 6px 8px;
  border: 1px solid rgba(211, 99, 99, 0.16);
  border-radius: 999px;
  color: #d9a6a6;
  background: rgba(211, 99, 99, 0.05);
  font-size: 10px;
}

#staging.active .staging-quiet-details {
  padding: 0;
  overflow: hidden;
}

#staging.active .staging-quiet-details > summary {
  cursor: pointer;
  padding: 14px 16px;
  color: #f0f5fb;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

#staging.active .staging-quiet-details[open] > summary {
  border-bottom: 1px solid rgba(170, 190, 215, 0.14);
}

#staging.active .staging-quiet-details > :not(summary) {
  margin: 16px;
}

@media (max-width: 1180px) {
  #staging.active .staging-primary-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  #staging.active .staging-lock-board > div {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  #staging.active .staging-qa-shell {
    padding: 10px !important;
  }

  #staging.active .staging-qa-shell .page-hero {
    grid-template-columns: 1fr !important;
    padding: 14px !important;
  }

  #staging.active .staging-purpose-line {
    align-items: stretch;
    flex-direction: column;
  }

  #staging.active .staging-purpose-line .primary-action {
    width: 100%;
  }

  #staging.active .staging-primary-grid,
  #staging.active .staging-lock-board > div,
  #staging.active .staging-route-matrix,
  #staging.active .staging-forbidden-work {
    grid-template-columns: 1fr;
  }

  #staging.active .staging-route-matrix span {
    grid-template-columns: 1fr;
  }

  #staging.active .staging-route-matrix em {
    justify-self: start;
  }

  #staging.active .staging-lock-board > header,
  #staging.active .staging-route-board > header {
    align-items: start;
    flex-direction: column;
    gap: 6px;
  }

  #staging.active .staging-decision-actions,
  #staging.active .staging-decision-actions a,
  #staging.active .staging-tracker-panel > a {
    width: 100%;
  }
}

/* 00 Alerts Desk premium mock terminal. */
body[data-active-view="alerts"] {
  --pcad-bg: #05080a;
  --pcad-panel: rgba(8, 18, 20, 0.94);
  --pcad-panel-2: rgba(11, 23, 25, 0.88);
  --pcad-line: rgba(218, 153, 61, 0.46);
  --pcad-line-soft: rgba(218, 153, 61, 0.22);
  --pcad-gold: #e2a84b;
  --pcad-gold-soft: #b9853b;
  --pcad-text: #f1dfbd;
  --pcad-muted: #a99f8b;
  --pcad-green: #87d85f;
  --pcad-red: #ff5145;
}

body[data-active-view="alerts"] .shell {
  display: grid !important;
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr) !important;
  min-height: 100vh;
  background:
    radial-gradient(circle at 18% 18%, rgba(226, 168, 75, 0.07), transparent 24%),
    linear-gradient(180deg, #071012 0%, #05080a 58%, #020405 100%) !important;
}

body[data-active-view="alerts"] .topbar {
  display: none !important;
}

body[data-active-view="alerts"] .rail {
  display: block !important;
}

body[data-active-view="alerts"] main {
  width: 100%;
  max-width: none;
  margin: 0;
  padding: 0 !important;
  background: var(--pcad-bg) !important;
}

body[data-active-view="alerts"] #alerts.active {
  padding: 0 !important;
}

.pcad-shell {
  min-height: 100vh;
  padding: 8px;
  color: var(--pcad-text);
  background:
    linear-gradient(rgba(226, 168, 75, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(226, 168, 75, 0.025) 1px, transparent 1px),
    radial-gradient(circle at 72% 18%, rgba(116, 209, 92, 0.08), transparent 24%),
    #030608;
  background-size: 44px 44px, 44px 44px, auto, auto;
  border: 1px solid var(--pcad-line-soft);
  box-shadow: inset 0 0 80px rgba(0, 0, 0, 0.78);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.pcad-topbar,
.pcad-panel,
.pcad-metric-card,
.pcad-playbook,
.pcad-purpose-strip,
.pcad-detail-layer,
.pcad-footer {
  border: 1px solid var(--pcad-line);
  background:
    linear-gradient(145deg, rgba(255, 255, 255, 0.035), transparent 42%),
    var(--pcad-panel);
  box-shadow:
    inset 0 1px 0 rgba(255, 224, 160, 0.08),
    0 0 28px rgba(0, 0, 0, 0.34);
}

.pcad-topbar {
  display: grid;
  grid-template-columns: 250px minmax(280px, 1fr) minmax(360px, auto) 230px;
  gap: 16px;
  align-items: center;
  min-height: 70px;
  padding: 10px 18px;
}

.pcad-brand,
.pcad-title-block,
.pcad-nav,
.pcad-officer {
  display: flex;
  align-items: center;
  min-width: 0;
}

.pcad-brand {
  gap: 14px;
  color: var(--pcad-gold);
  text-decoration: none;
  text-transform: uppercase;
}

.pcad-brand-mark,
.pcad-officer span {
  display: grid;
  place-items: center;
  border: 1px solid var(--pcad-gold);
  border-radius: 50%;
  color: var(--pcad-gold);
  background: rgba(226, 168, 75, 0.06);
}

.pcad-brand-mark {
  width: 46px;
  height: 46px;
  font-family: Georgia, serif;
  font-size: 14px;
  letter-spacing: 0;
}

.pcad-brand strong,
.pcad-brand em,
.pcad-title-block h2,
.pcad-panel-head span,
.pcad-stream-head h3,
.pcad-playbook h3,
.pcad-detail-title strong,
.pcad-detail-layer article > span,
.pcad-climate strong {
  font-family: Georgia, "Times New Roman", serif;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pcad-brand strong {
  display: block;
  color: var(--pcad-gold) !important;
  font-size: 25px;
  line-height: 0.9;
}

.pcad-brand em {
  display: block;
  margin-top: 4px;
  color: var(--pcad-gold) !important;
  font-size: 11px;
  font-style: normal;
  text-align: center;
}

.pcad-title-block {
  justify-content: space-between;
  gap: 16px;
  padding-left: 22px;
  border-left: 1px solid var(--pcad-line-soft);
}

.pcad-title-block h2 {
  margin: 0;
  color: var(--pcad-gold) !important;
  font-size: 31px;
  line-height: 1;
  text-shadow: 0 0 18px rgba(226, 168, 75, 0.16) !important;
}

.pcad-title-block p,
.pcad-panel-head small,
.pcad-stream-head span,
.pcad-metric-card p,
.pcad-system-card p,
.pcad-climate p,
.pcad-market-overview p,
.pcad-detail-layer p,
.pcad-detail-layer dd,
.pcad-footer,
.pcad-officer em {
  color: var(--pcad-muted);
}

.pcad-title-block p {
  margin: 4px 0 0;
  font-size: 13px;
}

.pcad-private,
.pcad-stream-actions button,
.pcad-filters button,
.pcad-purpose-strip button,
.pcad-system-card a,
.pcad-regime a {
  border: 1px solid var(--pcad-line);
  color: var(--pcad-gold);
  background: rgba(226, 168, 75, 0.06);
  text-transform: uppercase;
  text-decoration: none;
}

.pcad-private {
  flex: 0 0 auto;
  padding: 8px 16px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 800;
}

.pcad-nav {
  justify-content: center;
  gap: 18px;
}

.pcad-nav a {
  color: rgba(241, 223, 189, 0.54);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-decoration: none;
  text-transform: uppercase;
}

.pcad-nav a.active,
.pcad-nav a:hover {
  color: var(--pcad-gold);
}

.pcad-officer {
  justify-content: flex-end;
  gap: 12px;
  border-left: 1px solid var(--pcad-line-soft);
  padding-left: 18px;
}

.pcad-officer span {
  width: 42px;
  height: 42px;
  font-family: Georgia, serif;
}

.pcad-officer strong,
.pcad-officer em {
  display: block;
}

.pcad-officer strong {
  color: var(--pcad-text);
  font-size: 13px;
}

.pcad-officer em {
  font-size: 11px;
  font-style: normal;
}

.pcad-grid {
  display: grid;
  grid-template-columns: 305px minmax(0, 1fr) 405px;
  gap: 10px;
  width: 100%;
  padding: 10px 0 0 !important;
}

.pcad-left,
.pcad-center,
.pcad-right {
  display: grid;
  align-content: start;
  gap: 10px;
  min-width: 0;
}

.pcad-panel,
.pcad-metric-card,
.pcad-playbook {
  min-width: 0;
  border-radius: 6px;
  padding: 14px;
}

.pcad-panel-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.pcad-panel-head span,
.pcad-stream-head h3,
.pcad-playbook h3 {
  color: var(--pcad-gold) !important;
  font-size: 15px;
}

.pcad-panel-head small,
.pcad-panel-head a {
  font-size: 11px;
}

.pcad-panel-head a {
  color: var(--pcad-gold);
  text-decoration: none;
}

.pcad-source-list {
  position: relative;
  display: grid;
  gap: 9px;
}

.pcad-source-row {
  position: relative;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  min-height: 58px;
  padding: 8px 42px 8px 10px;
  border: 1px solid var(--pcad-line-soft);
  border-radius: 7px;
  background: rgba(255, 255, 255, 0.025);
}

.pcad-source-row::after {
  content: "";
  position: absolute;
  right: -14px;
  top: 50%;
  width: 28px;
