  background: rgba(255, 81, 69, 0.08);
}

.pcad-system-card {
  display: grid;
  gap: 12px;
}

.pcad-system-card span,
.pcad-climate span,
.pcad-regime > span,
.pcad-metric-card small {
  color: var(--pcad-gold);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pcad-system-card strong {
  color: var(--pcad-green) !important;
  font-family: Georgia, serif;
  font-size: 18px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pcad-system-card a,
.pcad-regime a {
