  justify-content: center;
  padding: 9px 12px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 800;
}

.pcad-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.pcad-purpose-strip {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  min-width: 0;
  border-radius: 6px;
  padding: 12px 14px;
}

.source-research-flow-card,
.research-desk-shell :is(.command-card, .glass-card, .truth-panel),
.pcad-research-intake {
  border-color: var(--px-border-soft, rgba(212, 175, 55, 0.18));
}

.source-research-flow-card {
  display: grid;
  align-content: start;
  gap: 14px;
}

.source-research-flow-card p,
.research-desk-shell p,
.research-desk-shell li,
.pcad-research-intake p,
.research-intake-card dd {
  color: var(--px-muted, #A8A096);
  line-height: 1.65;
}

.research-flow-steps,
.research-operating-loop {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
  min-width: 0;
}

.research-flow-steps span,
.research-operating-loop span {
  display: grid;
  gap: 6px;
  min-width: 0;
  padding: 10px;
  border: 1px solid var(--px-border-muted, rgba(246, 240, 228, 0.10));
  border-radius: var(--px-radius-sm, 10px);
  background: rgba(246, 240, 228, 0.035);
  color: var(--px-ivory, #F6F0E4);
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
}

.research-flow-steps em,
.research-operating-loop em {
  color: var(--px-gold, #D4AF37);
  font-size: 10px;
  font-style: normal;
}

.research-desk-shell {
  display: grid;
  gap: 24px;
  max-width: 100%;
  overflow-x: hidden;
}

.research-desk-hero {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(280px, 0.5fr);
  gap: 20px;
  align-items: stretch;
  padding: clamp(22px, 4vw, 42px);
  border: 1px solid var(--px-border-soft, rgba(212, 175, 55, 0.18));
  border-radius: var(--px-radius-lg, 22px);
  background:
