  box-shadow: var(--px-shadow-card, 0 18px 60px rgba(0, 0, 0, 0.32));
}

.research-desk-hero h2 {
  margin: 8px 0 12px;
  color: var(--px-ivory, #F6F0E4);
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(32px, 5vw, 58px);
  line-height: 0.95;
}

.research-desk-hero .truth-panel {
  margin: 0;
}

.research-operating-loop {
  grid-template-columns: repeat(7, minmax(120px, 1fr));
  overflow-x: auto;
  padding-bottom: 4px;
}

.research-builder-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.8fr) minmax(260px, 0.65fr);
  gap: 16px;
  align-items: start;
}

.research-builder-card,
.research-handoff-card,
.research-route-card,
.research-anatomy-grid > *,
.research-packet-card,
.pcad-research-intake {
  border-radius: var(--px-radius-md, 16px);
}

.research-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin: 16px 0;
}

.research-form-grid label {
  display: grid;
  gap: 6px;
  color: var(--px-muted, #A8A096);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.research-form-grid label.wide {
  grid-column: 1 / -1;
}

.research-form-grid input,
.research-form-grid textarea {
  width: 100%;
  min-width: 0;
  border: 1px solid var(--px-border-muted, rgba(246, 240, 228, 0.10));
  border-radius: var(--px-radius-sm, 10px);
  background: rgba(5, 5, 5, 0.62);
  color: var(--px-ivory, #F6F0E4);
  padding: 11px 12px;
  font: 500 13px/1.45 Inter, ui-sans-serif, system-ui, sans-serif;
}

.research-form-grid textarea {
  min-height: 82px;
  resize: vertical;
}

.research-handoff-list,
.research-packet-list {
  display: grid;
  gap: 12px;
}

.research-handoff-list article {
  display: grid;
  gap: 8px;
  padding: 12px;
  border: 1px solid var(--px-border-muted, rgba(246, 240, 228, 0.10));
  border-radius: var(--px-radius-sm, 10px);
  background: rgba(5, 5, 5, 0.34);
}

.research-handoff-list div,
.research-packet-head,
.research-intake-card > div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  min-width: 0;
}

.research-handoff-list strong,
.research-packet-card h4,
.research-intake-card strong {
  color: var(--px-ivory, #F6F0E4);
}

.research-handoff-list em,
.research-packet-head span,
.research-intake-card > div strong {
  color: var(--px-gold, #D4AF37);
  font-style: normal;
  font-weight: 900;
}

.research-handoff-list span,
.research-handoff-list small {
  color: var(--px-muted, #A8A096);
  font-size: 12px;
}

.research-route-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.research-route-actions button,
.research-intake-card a {
  border: 1px solid var(--px-border-soft, rgba(212, 175, 55, 0.18));
  border-radius: var(--px-radius-sm, 10px);
  background: rgba(246, 240, 228, 0.04);
  color: var(--px-ivory, #F6F0E4);
  padding: 9px 11px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-decoration: none;
  text-transform: uppercase;
}

.research-route-actions button.primary,
.research-intake-card a {
  background: linear-gradient(135deg, var(--px-gold, #D4AF37), var(--px-antique-gold, #B68A3A));
  color: var(--px-black, #050505);
}

.research-anatomy-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.research-anatomy-grid ul {
  margin: 12px 0 0;
  padding-left: 18px;
}

.research-recent-section {
  display: grid;
  gap: 14px;
}

.research-packet-list {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.research-packet-card {
  display: grid;
  gap: 12px;
  min-width: 0;
  padding: 16px;
  border: 1px solid var(--px-border-muted, rgba(246, 240, 228, 0.10));
  background: rgba(17, 17, 17, 0.92);
  box-shadow: var(--px-shadow-soft, 0 10px 30px rgba(0, 0, 0, 0.22));
}

.research-packet-head em {
  color: var(--px-muted, #A8A096);
  font-size: 10px;
  font-style: normal;
  text-align: right;
  text-transform: uppercase;
}

.research-packet-meta {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.research-packet-meta span,
.research-intake-empty {
  padding: 9px;
  border: 1px solid var(--px-border-muted, rgba(246, 240, 228, 0.10));
  border-radius: var(--px-radius-sm, 10px);
  background: rgba(246, 240, 228, 0.035);
  color: var(--px-muted, #A8A096);
  font-size: 11px;
}

.research-packet-meta strong {
  display: block;
  color: var(--px-ivory, #F6F0E4);
}

.pcad-research-intake {
  display: grid;
  gap: 12px;
}

.research-intake-card {
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid rgba(212, 175, 55, 0.22);
  border-radius: var(--px-radius-sm, 10px);
  background: rgba(212, 175, 55, 0.055);
}

.research-intake-card dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
  margin: 0;
}

.research-intake-card div {
  min-width: 0;
}

.research-intake-card dt {
  color: var(--px-gold, #D4AF37);
  font-size: 10px;
  font-weight: 900;
  text-transform: uppercase;
}

.research-intake-card dd {
  margin: 3px 0 0;
  overflow-wrap: anywhere;
}

@media (max-width: 1240px) {
  .research-builder-grid,
  .research-anatomy-grid,
  .research-packet-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .research-route-card {
    grid-column: 1 / -1;
  }
}

@media (max-width: 820px) {
  .research-desk-hero,
  .research-builder-grid,
  .research-anatomy-grid,
  .research-packet-list,
  .research-form-grid,
  .research-intake-card dl {
    grid-template-columns: 1fr;
  }

  .research-flow-steps {
    grid-template-columns: 1fr;
  }

  .research-route-card {
    grid-column: auto;
  }

  .research-route-actions button,
  .research-intake-card a {
    width: 100%;
  }

  .research-packet-meta {
    grid-template-columns: 1fr;
  }
}

.pcad-purpose-strip span {
  color: var(--pcad-gold);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pcad-purpose-strip p {
  margin: 0;
  color: var(--pcad-muted);
  font-size: 13px;
  line-height: 1.45;
}

.pcad-purpose-strip button {
  min-height: 34px;
  border-radius: 5px;
  padding: 0 14px;
  color: #071012;
  background: linear-gradient(180deg, #f1c46a, #b97831);
  font-size: 11px;
  font-weight: 900;
  white-space: nowrap;
}

.pcad-metric-card {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 2px 12px;
  min-height: 132px;
  align-content: center;
}

.pcad-metric-card small,
.pcad-metric-card strong,
.pcad-metric-card p {
  grid-column: 2;
  margin: 0;
}

.pcad-metric-card strong {
  color: var(--pcad-text) !important;
  font-family: Georgia, serif;
  font-size: 36px;
  line-height: 1;
}

.pcad-metric-card strong em {
  color: var(--pcad-muted) !important;
  font-size: 14px;
  font-style: normal;
}

.pcad-metric-card p {
  font-size: 12px;
}

.pcad-icon,
.pcad-gauge {
  grid-column: 1;
  grid-row: 1 / span 3;
  align-self: center;
}

.pcad-icon {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  border: 1px solid var(--pcad-line);
  border-radius: 50%;
}

.pcad-icon::before {
  color: var(--pcad-gold);
  font-family: Georgia, serif;
  font-size: 23px;
}

.pcad-icon.bell::before { content: "!"; }
.pcad-icon.shield::before { content: "*"; }
.pcad-icon.network::before { content: "+"; }

.pcad-gauge,
.pcad-sentiment-gauge {
  display: grid;
  place-items: center;
  border-radius: 50%;
  background:
    radial-gradient(circle at center, #071012 54%, transparent 56%),
    conic-gradient(var(--pcad-green) 0deg var(--gauge), var(--pcad-red) var(--gauge) 360deg);
}

.pcad-gauge {
  width: 60px;
  height: 60px;
}

.pcad-gauge strong {
  grid-column: auto;
  color: var(--pcad-green) !important;
  font-size: 19px;
}

.pcad-gauge-card p b {
  color: var(--pcad-green);
}

.pcad-gauge-card p .danger,
.pcad-mini-table .down,
.pcad-sentiment .danger,
.pcad-regime .danger {
  color: var(--pcad-red);
}

.pcad-stream-panel {
