}

.pcad-stream-head small {
  color: var(--pcad-muted);
  font-size: 12px;
}

.pcad-table {
  display: grid;
  gap: 7px;
  margin-top: 9px;
  max-width: 100%;
  overflow-x: auto;
}

.pcad-table-row {
  display: grid;
  grid-template-columns: minmax(150px, 1.1fr) minmax(130px, 0.8fr) minmax(110px, 0.7fr) minmax(140px, 0.85fr) minmax(180px, 1fr) minmax(220px, 1.35fr) minmax(130px, 0.75fr);
