}

.pcad-candidate-detail summary {
  cursor: pointer;
  list-style: none;
}

.pcad-candidate-detail summary::-webkit-details-marker {
  display: none;
}

.pcad-row-packet {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin: -2px 0 6px;
  padding: 10px;
