  border-radius: 0 0 5px 5px;
  background: rgba(0, 0, 0, 0.22);
}

.pcad-row-packet span {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.pcad-row-packet strong {
  color: var(--pcad-gold-soft);
  font-size: 11px;
  text-transform: uppercase;
}

.pcad-row-packet small {
  color: var(--pcad-muted);
  font-size: 12px;
  line-height: 1.35;
}

.pcad-table-row span {
  min-width: 0;
