  color: var(--pcad-green);
  background: rgba(135, 216, 95, 0.08);
  font-size: 10px;
  font-style: normal;
  text-transform: uppercase;
}

.pcad-table-row.put em {
  border-color: rgba(255, 81, 69, 0.25);
  color: var(--pcad-red);
  background: rgba(255, 81, 69, 0.08);
