}

.pcad-detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.pcad-detail-grid article {
  display: grid;
  gap: 10px;
  min-width: 0;
  padding: 12px;
  border: 1px solid rgba(226, 168, 75, 0.13);
  border-radius: 5px;
  background: rgba(0, 0, 0, 0.18);
}

.pcad-detail-layer dl {
  display: grid;
  gap: 7px;
  margin: 0;
}

.pcad-detail-layer dl div {
  display: grid;
  grid-template-columns: minmax(120px, 0.75fr) minmax(0, 1fr);
  gap: 10px;
  padding-bottom: 7px;
  border-bottom: 1px solid rgba(226, 168, 75, 0.1);
}

.pcad-detail-layer dt {
  color: var(--pcad-gold-soft);
  font-size: 11px;
  text-transform: uppercase;
}

.pcad-detail-layer dd {
  margin: 0;
  font-size: 12px;
  line-height: 1.35;
}

.pcad-thesis-card p {
  margin: 0;
  color: var(--pcad-text);
  font-size: 13px;
  line-height: 1.45;
}

.pcad-thesis-card ul,
.pcad-projected ul {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.pcad-thesis-card li,
.pcad-projected li {
  display: grid;
  gap: 3px;
  color: var(--pcad-muted);
  font-size: 12px;
  line-height: 1.35;
}

.pcad-thesis-card li strong,
.pcad-projected li strong {
  color: var(--pcad-gold-soft);
  font-size: 11px;
  text-transform: uppercase;
}

.pcad-safety-copy {
  margin: 0;
  padding: 10px 12px;
  border: 1px solid rgba(226, 168, 75, 0.13);
  border-radius: 5px;
  background: rgba(226, 168, 75, 0.04);
  font-size: 12px;
  line-height: 1.45;
}

.pcad-playbooks {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.pcad-playbook {
  display: grid;
  grid-template-columns: minmax(260px, 1.2fr) minmax(190px, 0.8fr);
  gap: 12px;
  min-height: 255px;
}

.pcad-playbook h3 {
  grid-column: 1 / -1;
  margin: 0;
}

.pcad-play-chart {
  position: relative;
  display: grid;
  align-items: end;
  min-height: 150px;
  border: 1px solid rgba(226, 168, 75, 0.12);
  background:
    linear-gradient(rgba(226, 168, 75, 0.06) 1px, transparent 1px),
    linear-gradient(90deg, rgba(226, 168, 75, 0.04) 1px, transparent 1px),
    rgba(0, 0, 0, 0.2);
  background-size: 22px 22px;
  padding: 18px;
}

.pcad-play-chart .pcad-spark {
  height: 118px;
}

.pcad-play-chart span {
  position: absolute;
  left: 42%;
  top: 34%;
  color: var(--pcad-gold);
  font-family: Georgia, serif;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pcad-playbook ul {
  display: grid;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.pcad-playbook li {
  padding: 8px 10px;
  border: 1px solid rgba(226, 168, 75, 0.14);
  border-radius: 5px;
  color: var(--pcad-muted);
  background: rgba(255, 255, 255, 0.025);
  font-size: 12px;
}

.pcad-entry {
  display: grid;
  gap: 5px;
  padding: 10px;
  border: 1px solid var(--pcad-line-soft);
  border-radius: 5px;
}

.pcad-entry span,
.pcad-entry em {
  color: var(--pcad-gold);
  font-size: 11px;
  font-style: normal;
  text-transform: uppercase;
}

.pcad-entry strong {
  color: var(--pcad-green);
}

.pcad-playbook.puts .pcad-entry strong {
  color: var(--pcad-red);
  font-size: 12px;
  line-height: 1.35;
}

.pcad-right .pcad-panel {
  display: grid;
  gap: 10px;
}

.pcad-market-overview > div:first-child,
.pcad-climate > div:first-child {
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.pcad-market-overview span,
.pcad-climate span {
  color: var(--pcad-gold);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pcad-market-overview small,
.pcad-climate small {
  color: var(--pcad-muted);
  font-size: 11px;
}

.pcad-market-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.pcad-market-grid span,
.pcad-sentiment-list span,
.pcad-system-list a {
  display: grid;
  gap: 3px;
  min-width: 0;
  padding: 8px;
  border: 1px solid rgba(226, 168, 75, 0.12);
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.025);
}

.pcad-market-grid strong,
.pcad-sentiment-list strong,
.pcad-system-list strong {
  color: var(--pcad-text) !important;
  font-size: 12px;
  line-height: 1.2;
}

.pcad-market-grid small,
.pcad-sentiment-list em,
.pcad-system-list em {
  color: var(--pcad-muted);
  font-size: 11px;
  font-style: normal;
  line-height: 1.25;
}

.pcad-system-list,
.pcad-sentiment-list {
  display: grid;
  gap: 7px;
}

.pcad-system-list a {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  color: inherit;
  text-decoration: none;
}

.pcad-projected li span {
  color: var(--pcad-muted);
}

.pcad-climate strong {
  color: var(--pcad-green) !important;
  font-size: 26px;
}

.pcad-filters > div {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.pcad-filters button:nth-child(n + 5) {
  grid-template-columns: auto;
}

body[data-active-view="alerts"] #alerts.active .pcad-shell :is(button, a) {
  border-color: var(--pcad-line) !important;
}

body[data-active-view="alerts"] #alerts.active .pcad-table-row,
body[data-active-view="alerts"] #alerts.active button.pcad-table-row {
  color: var(--pcad-muted) !important;
  background: rgba(3, 8, 10, 0.74) !important;
  border-color: rgba(226, 168, 75, 0.15) !important;
  border-radius: 5px !important;
  box-shadow: none !important;
}

body[data-active-view="alerts"] #alerts.active .pcad-table-row.head {
  background: transparent !important;
  border-color: transparent !important;
  color: var(--pcad-gold-soft) !important;
}

body[data-active-view="alerts"] #alerts.active :is(button, summary).pcad-table-row:hover,
body[data-active-view="alerts"] #alerts.active :is(button, summary).pcad-table-row.active {
  border-color: var(--pcad-line) !important;
  background: rgba(10, 20, 20, 0.92) !important;
  box-shadow: inset 0 0 22px rgba(226, 168, 75, 0.06) !important;
}

body[data-active-view="alerts"] #alerts.active .pcad-table-row b {
  color: var(--pcad-green) !important;
}

body[data-active-view="alerts"] #alerts.active .pcad-table-row.put b {
  color: var(--pcad-red) !important;
}

body[data-active-view="alerts"] #alerts.active .pcad-table-row em {
  color: var(--pcad-green) !important;
  background: rgba(135, 216, 95, 0.08) !important;
  border-color: rgba(135, 216, 95, 0.25) !important;
}

body[data-active-view="alerts"] #alerts.active .pcad-table-row.put em {
  color: var(--pcad-red) !important;
  background: rgba(255, 81, 69, 0.08) !important;
  border-color: rgba(255, 81, 69, 0.25) !important;
}

body[data-active-view="alerts"] #alerts.active .pcad-table-row .pcad-status-chip,
body[data-active-view="alerts"] #alerts.active .pcad-table-row.put .pcad-status-chip {
  color: var(--pcad-gold-soft) !important;
  background: rgba(226, 168, 75, 0.06) !important;
  border-color: rgba(226, 168, 75, 0.22) !important;
}

body[data-active-view="alerts"] #alerts.active .pcad-stream-actions button,
body[data-active-view="alerts"] #alerts.active .pcad-filters button,
body[data-active-view="alerts"] #alerts.active .pcad-purpose-strip button {
  color: var(--pcad-gold) !important;
  background: rgba(226, 168, 75, 0.06) !important;
  border-color: var(--pcad-line) !important;
  border-radius: 5px !important;
  box-shadow: none !important;
}

body[data-active-view="alerts"] #alerts.active .pcad-stream-actions button.primary,
body[data-active-view="alerts"] #alerts.active .pcad-filters button.active,
body[data-active-view="alerts"] #alerts.active .pcad-purpose-strip button {
  color: #071012 !important;
  background: linear-gradient(180deg, #f1c46a, #b97831) !important;
}

.pcad-mini-table {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr 1fr;
  gap: 0;
  font-size: 12px;
}

.pcad-mini-table > * {
  padding: 6px 4px;
  border-bottom: 1px solid rgba(226, 168, 75, 0.12);
}

.pcad-mini-table span {
  color: var(--pcad-gold-soft);
  font-family: Georgia, serif;
  text-transform: uppercase;
}

.pcad-mini-table strong,
.pcad-mini-table b {
  color: var(--pcad-text);
}

.pcad-mini-table strong {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  gap: 6px;
  align-items: center;
}

.pcad-mini-table strong i {
  width: 22px;
  height: 22px;
  font-size: 10px;
}

.pcad-mini-table strong small {
  grid-column: 2;
  color: var(--pcad-muted);
  font-size: 10px;
  font-weight: 500;
  line-height: 1.15;
}

.pcad-mini-table em {
  color: var(--pcad-muted);
  font-style: normal;
}

.pcad-mini-table .up {
  color: var(--pcad-green);
}

.pcad-sentiment-gauge {
  justify-self: center;
  width: 128px;
  height: 128px;
}

.pcad-sentiment-gauge strong,
.pcad-sentiment-gauge span {
  display: block;
  text-align: center;
}

.pcad-sentiment-gauge strong {
  color: var(--pcad-green) !important;
  font-size: 20px;
}

.pcad-sentiment-gauge span {
  max-width: 72px;
  color: var(--pcad-muted);
  font-size: 10px;
  text-transform: uppercase;
}

.pcad-sentiment p,
.pcad-candidate-mix p,
.pcad-regime p {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin: 0;
}

.pcad-sentiment p b,
.pcad-candidate-mix p b,
.pcad-regime p strong {
  color: var(--pcad-green);
  font-size: 12px;
  text-transform: uppercase;
}

.pcad-wave {
  padding: 6px 0;
}

.pcad-footer {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  margin-top: 10px;
  padding: 12px 20px;
  color: var(--pcad-muted);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pcad-footer strong {
  color: rgba(241, 223, 189, 0.68);
  font-weight: 600;
}

@media (max-width: 1500px) {
  .pcad-topbar {
    grid-template-columns: 220px minmax(260px, 1fr);
  }

  .pcad-nav {
    grid-column: 1 / -1;
    justify-content: flex-start;
  }

  .pcad-officer {
    display: none;
  }

  .pcad-grid {
    grid-template-columns: 260px minmax(0, 1fr);
  }

  .pcad-left {
    grid-template-columns: 1fr;
  }

  .pcad-source-panel {
    grid-column: auto;
  }

  .pcad-right {
    grid-column: 1 / -1;
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .pcad-playbooks {
    grid-template-columns: 1fr;
  }

  .pcad-stream-panel {
    min-width: 0;
    overflow: hidden;
  }

  .pcad-table {
    display: block;
    min-width: 0;
    max-width: 100%;
    overflow-x: auto;
  }

  .pcad-table-row {
    min-width: 0;
    grid-template-columns: minmax(140px, 1.1fr) minmax(120px, 0.8fr) minmax(96px, 0.7fr) minmax(130px, 0.85fr) minmax(160px, 1fr) minmax(180px, 1.25fr) minmax(110px, 0.75fr);
    font-size: 12px;
  }

  .pcad-candidate-detail {
    min-width: 0;
  }
}

@media (max-width: 1220px) {
  .pcad-topbar,
  .pcad-grid,
  .pcad-playbooks {
    grid-template-columns: 1fr;
  }

  .pcad-nav {
    justify-content: flex-start;
    flex-wrap: wrap;
  }

  .pcad-left,
  .pcad-right {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .pcad-source-panel {
    grid-column: 1 / -1;
  }

  .pcad-table {
    overflow-x: auto;
  }

  .pcad-table-row {
    min-width: 980px;
  }

  .pcad-candidate-detail {
    min-width: 980px;
  }
}

@media (max-width: 760px) {
  body[data-active-view="alerts"] .shell {
    grid-template-columns: 1fr !important;
  }

  body[data-active-view="alerts"] .rail {
    position: relative !important;
    top: auto !important;
    height: auto !important;
    max-height: none !important;
  }

  .pcad-shell {
    padding: 6px;
  }

  .pcad-topbar,
  .pcad-title-block,
  .pcad-footer {
    align-items: stretch;
    flex-direction: column;
  }

  .pcad-title-block {
    padding-left: 0;
    border-left: 0;
  }

  .pcad-title-block h2 {
    font-size: 26px;
  }

  .pcad-metrics,
  .pcad-purpose-strip,
  .pcad-detail-layer header,
  .pcad-detail-grid,
  .pcad-detail-layer dl div,
  .pcad-left,
  .pcad-right,
  .pcad-playbook,
  .pcad-stream-actions,
  .pcad-filters > div {
    grid-template-columns: 1fr;
  }

  .pcad-metric-card {
    min-height: 112px;
  }

  .pcad-purpose-strip button {
    width: 100%;
  }

  .pcad-table {
    display: grid;
    overflow-x: visible;
  }

  .pcad-table-row.head {
    display: none;
  }

  .pcad-table-row,
  body[data-active-view="alerts"] #alerts.active .pcad-table-row,
  body[data-active-view="alerts"] #alerts.active button.pcad-table-row {
    grid-template-columns: 1fr;
    min-width: 0;
    gap: 10px;
    padding: 12px;
  }

  .pcad-candidate-detail {
    min-width: 0;
  }

  .pcad-row-packet {
    grid-template-columns: 1fr;
  }

  .pcad-company-cell {
    grid-template-columns: 42px minmax(0, 1fr);
  }

  .pcad-detail-layer header {
    text-align: left;
  }

  .pcad-detail-score {
    text-align: left;
  }

  .pcad-detail-layer dl div {
    gap: 4px;
  }

  .pcad-footer {
    display: grid;
  }
}

/* CSS Consolidation / Premium Visual System Cleanup.
   This final compatibility layer keeps existing route classes intact while
   normalizing the shared Pickaxe surface, card, button, chip, table, and
   responsive rules around the sovereign black/gold visual system. */
:root {
  --px-black: #050505 !important;
  --px-graphite: #111111 !important;
  --px-charcoal: #1A1712 !important;
  --px-ivory: #F6F0E4 !important;
  --px-paper: #EFE3CF !important;
  --px-gold: #D4AF37 !important;
  --px-antique-gold: #B68A3A !important;
  --px-bronze: #7A5A28 !important;
  --px-sage: #6F8068 !important;
  --px-risk: #9A4E45 !important;
  --px-muted: #A8A096 !important;
  --px-radius-xs: 8px !important;
  --px-radius-sm: 10px !important;
  --px-radius-md: 16px !important;
  --px-radius-lg: 22px !important;
  --px-radius-xl: 28px !important;
  --px-border-soft: rgba(212, 175, 55, 0.18) !important;
  --px-border-muted: rgba(246, 240, 228, 0.10) !important;
  --px-border-quiet: rgba(168, 160, 150, 0.16) !important;
  --px-card: rgba(17, 17, 17, 0.92) !important;
  --px-card-raised: rgba(26, 23, 18, 0.88) !important;
  --px-card-quiet: rgba(246, 240, 228, 0.035) !important;
  --px-shadow-card: 0 18px 60px rgba(0, 0, 0, 0.32) !important;
  --px-shadow-soft: 0 10px 30px rgba(0, 0, 0, 0.22) !important;
  --px-transition-fast: 150ms ease !important;
  --px-transition: 220ms ease !important;
  --bg: var(--px-black) !important;
  --bg-main: var(--px-black) !important;
  --black: var(--px-black) !important;
  --panel: var(--px-graphite) !important;
  --panel-2: var(--px-charcoal) !important;
  --surface-1: var(--px-graphite) !important;
  --surface-2: var(--px-charcoal) !important;
  --surface-3: #201c15 !important;
  --line: var(--px-border-muted) !important;
  --border-soft: var(--px-border-muted) !important;
  --text: var(--px-ivory) !important;
  --muted: var(--px-muted) !important;
  --green: var(--px-sage) !important;
  --red: var(--px-risk) !important;
  --amber: var(--px-gold) !important;
  --gold: var(--px-gold) !important;
  --cyan: var(--px-muted) !important;
  --teal: var(--px-muted) !important;
  --blue: var(--px-sage) !important;
  --violet: var(--px-antique-gold) !important;
  --radius: var(--px-radius-md) !important;
  --glow-cyan: rgba(168, 160, 150, 0.10) !important;
  --glow-gold: rgba(212, 175, 55, 0.14) !important;
  --glow-violet: rgba(182, 138, 58, 0.10) !important;
}

html,
body {
  max-width: 100%;
  overflow-x: hidden;
  background:
    radial-gradient(circle at 78% -10%, rgba(212, 175, 55, 0.06), transparent 30%),
    linear-gradient(180deg, var(--px-black) 0%, #080806 54%, #030303 100%) !important;
  color: var(--px-ivory) !important;
}

body::before {
  opacity: 0.28;
}

.shell {
  width: 100%;
  min-width: 0;
  background: transparent !important;
}

main {
  min-width: 0;
  max-width: 100%;
  background: transparent !important;
}

.view,
.page-shell,
.staging-qa-shell,
.archive-declutter-shell,
.source-hub-shell,
.dashboard-shell {
  min-width: 0;
  max-width: 100%;
}

.rail {
  z-index: var(--px-z-sidebar, 30);
  border-right: 1px solid var(--px-border-muted) !important;
  background:
    radial-gradient(circle at 50% 0%, rgba(212, 175, 55, 0.08), transparent 30%),
    linear-gradient(180deg, rgba(17, 17, 17, 0.98), rgba(5, 5, 5, 0.99)) !important;
  box-shadow: 18px 0 60px rgba(0, 0, 0, 0.18);
}

.brand,
.rail-card,
.rail-quote {
  border-color: var(--px-border-muted) !important;
  border-radius: var(--px-radius-md) !important;
  background: rgba(246, 240, 228, 0.035) !important;
  box-shadow: none !important;
}

.rail-quote {
  display: block !important;
  color: var(--px-muted) !important;
}

.rail-quote .label,
.rail-quote strong,
.sidebar-group-label {
  color: var(--px-gold) !important;
}

.nav-button.sidebar-item {
  border: 1px solid transparent !important;
  border-radius: var(--px-radius-sm) !important;
  background: rgba(246, 240, 228, 0.025) !important;
  box-shadow: none !important;
  color: var(--px-muted) !important;
  transition: background var(--px-transition-fast), border-color var(--px-transition-fast), color var(--px-transition-fast), transform var(--px-transition-fast);
}

.nav-button.sidebar-item:hover {
  border-color: var(--px-border-soft) !important;
  background: rgba(212, 175, 55, 0.055) !important;
  color: var(--px-ivory) !important;
  transform: translateX(1px);
}

.nav-button.sidebar-item.active {
  border-color: rgba(212, 175, 55, 0.38) !important;
  background:
    linear-gradient(90deg, rgba(212, 175, 55, 0.13), rgba(246, 240, 228, 0.028)) !important;
  box-shadow: inset 3px 0 0 var(--px-gold) !important;
  color: var(--px-ivory) !important;
}

.nav-button.sidebar-item .sidebar-code {
  border-color: rgba(246, 240, 228, 0.12) !important;
  background: rgba(0, 0, 0, 0.18) !important;
  color: var(--px-muted) !important;
}

.nav-button.sidebar-item.active .sidebar-code,
.dashboard-pin .sidebar-code {
  border-color: rgba(212, 175, 55, 0.40) !important;
  color: var(--px-gold) !important;
  background: rgba(212, 175, 55, 0.085) !important;
}

.topbar,
.panel,
.glass-card,
.command-card,
.truth-panel,
.metric-card,
.mini-card,
.signal-card,
.summary-card,
.vault-card,
.compact-card,
.source-card,
.archive-intel-card,
.pipeline-card,
.integration-card-grid article,
.route-status-board article,
.tracker-area-card,
.latest-session-card,
.tracker-add-card,
.archive-system-card,
.jarvis-card,
.ceob-briefing-card,
.project-route-grid article,
.pc-panel,
.pc-card,
.pc-metric-card,
.alerts-focus-hero,
.alerts-focus-primary,
.alerts-focus-checks,
.alerts-focus-queue,
#staging.active .staging-purpose-line,
#staging.active .staging-command-panel,
#staging.active .staging-quiet-band,
