}

.premium-table tbody tr,
.source-table span,
.tracker-table > *,
.ownership-table > * {
  border-color: var(--px-border-muted) !important;
}

.premium-table tbody tr:hover,
.source-table span:hover,
.tracker-table > *:hover {
  background: rgba(212, 175, 55, 0.045) !important;
}

body[data-active-view="alerts"] {
  --pcad-bg: var(--px-black);
  --pcad-panel: rgba(17, 17, 17, 0.94);
  --pcad-panel-2: rgba(26, 23, 18, 0.88);
  --pcad-line: rgba(212, 175, 55, 0.40);
  --pcad-line-soft: rgba(212, 175, 55, 0.18);
  --pcad-gold: var(--px-gold);
  --pcad-gold-soft: var(--px-antique-gold);
  --pcad-text: var(--px-ivory);
  --pcad-muted: var(--px-muted);
  --pcad-green: var(--px-sage);
  --pcad-red: var(--px-risk);
}

.pcad-topbar,
.pcad-panel,
.pcad-metric-card,
.pcad-playbook,
.pcad-purpose-strip,
.pcad-detail-layer,
.pcad-footer {
  border-radius: var(--px-radius-md) !important;
  box-shadow: var(--px-shadow-soft) !important;
}

.pcad-table-row,
body[data-active-view="alerts"] #alerts.active .pcad-table-row,
body[data-active-view="alerts"] #alerts.active button.pcad-table-row {
  border-radius: var(--px-radius-sm) !important;
}

.pcad-table-row em {
  border-radius: 999px !important;
}

@media (max-width: 1180px) {
  .shell {
    grid-template-columns: minmax(220px, var(--sidebar-width)) minmax(0, 1fr);
  }

  .page-shell,
  .view.active {
    padding-inline: clamp(12px, 2vw, 20px);
  }
}

@media (max-width: 760px) {
  html,
  body,
  .shell,
  main,
  .view,
  .page-shell {
    width: 100%;
    max-width: 100%;
    overflow-x: hidden;
  }

  .shell {
    display: grid !important;
    grid-template-columns: 1fr !important;
  }

  .rail {
    position: relative !important;
    top: auto !important;
    width: 100%;
    height: auto !important;
    max-height: none !important;
    border-right: 0 !important;
    border-bottom: 1px solid var(--px-border-muted) !important;
  }

  main {
    padding: 0 !important;
  }

  .topbar,
  .panel,
  .glass-card,
  .command-card,
  .truth-panel,
  .metric-card,
  .vault-card,
  .source-card,
  .archive-intel-card,
  .pc-panel,
  .pc-card,
  .pc-metric-card,
  .alerts-focus-hero,
  .alerts-focus-primary,
  .alerts-focus-checks,
  .alerts-focus-queue {
    border-radius: var(--px-radius-md) !important;
  }

  .primary-action,
  .secondary-action,
  .pc-action-btn {
    width: 100%;
    min-height: 40px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.001ms !important;
  }
}

/* Landing Page + Services / Pricing */
.founder-profile.landing-profile {
  padding: 0 !important;
}

.access-page-shell {
