    linear-gradient(145deg, rgba(246, 240, 228, 0.05), rgba(246, 240, 228, 0.012) 44%),
    rgba(10, 10, 10, 0.96);
}

.proof-work-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
}

.proof-work-heading .access-section-head {
  margin-bottom: 0;
}

.proof-work-controls {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 0 0 auto;
}

.proof-work-controls span {
  min-width: 64px;
  color: var(--px-gold);
  font-family: "IBM Plex Mono", monospace;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.proof-work-controls button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  border: 1px solid rgba(212, 175, 55, 0.32);
  border-radius: 50%;
  background: rgba(246, 240, 228, 0.035);
  color: var(--px-ivory);
