  transform: translateY(-1px);
}

.proof-work-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 28px;
}

.proof-work-card {
  display: grid;
  grid-template-rows: auto 1fr auto auto;
