.access-request-card {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  padding: 22px;
}

.access-request-card label {
  display: grid;
  gap: 8px;
  color: var(--px-gold);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.access-request-card label:nth-child(4),
.access-request-card label:nth-child(5),
.access-request-card button,
.access-request-card p {
  grid-column: 1 / -1;
}

.access-request-card input,
.access-request-card textarea,
.access-request-card select {
  width: 100%;
  border: 1px solid var(--px-border-muted);
  border-radius: var(--px-radius-sm);
  background: rgba(5, 5, 5, 0.48);
  color: var(--px-ivory);
  padding: 12px 13px;
  outline: none;
}

.access-request-card input:focus,
.access-request-card textarea:focus,
.access-request-card select:focus {
  border-color: rgba(212, 175, 55, 0.42);
}

.access-request-card p {
  margin: 0;
  text-align: center;
}

.access-footer {
  display: flex;
  justify-content: space-between;
  gap: 22px;
}

.access-footer strong,
.access-footer span,
.access-footer small {
  display: block;
}

.access-footer strong {
  color: var(--px-ivory);
  font-family: Georgia, "Times New Roman", serif;
  font-size: 24px;
}

.access-footer span,
.access-footer a {
  color: var(--px-gold);
}

.access-footer a {
  font-size: 12px;
  font-weight: 800;
  text-decoration: none;
  text-transform: uppercase;
}

@media (max-width: 1180px) {
  .access-hero,
  .access-safety-band {
    grid-template-columns: 1fr;
  }

  .access-card-grid.four-up,
  .access-card-grid.modules,
  .access-card-grid.difference-grid,
  .access-generator-grid,
  .access-tag-grid,
  .access-loop,
  .access-tier-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .access-safety-band strong {
    grid-column: auto;
  }
}

@media (max-width: 760px) {
  .access-page-shell {
    padding: 10px;
  }

  .access-hero,
  .access-section,
  .access-safety-band,
  .access-footer {
    border-radius: var(--px-radius-lg);
    padding: 20px;
  }

  .access-card-grid.four-up,
  .access-card-grid.modules,
  .access-card-grid.difference-grid,
  .access-generator-grid,
  .access-tag-grid,
  .access-loop,
  .access-tier-grid,
  .access-preview-grid,
  .access-request-card {
    grid-template-columns: 1fr;
  }

  .access-hero-actions a,
  .access-tier-card a,
  .access-request-card button {
    width: 100% !important;
  }

  .access-footer {
    display: grid;
  }

  .proof-work-heading {
    display: grid;
    align-items: start;
  }

  .proof-work-controls {
    justify-content: space-between;
  }

  .proof-work-controls span {
    margin-right: auto;
  }

  .proof-work-grid {
    grid-template-columns: minmax(0, 1fr);
    margin-top: 22px;
  }

  .proof-work-card {
    min-height: 0;
    padding: 20px;
  }

  .proof-work-card:nth-child(2) {
    display: none;
  }

  .proof-work-card-head,
  .proof-work-card-meta {
    align-items: flex-start;
  }

  .proof-work-card-head strong {
    max-width: 150px;
  }

  .proof-work-card blockquote {
    font-size: clamp(22px, 7vw, 30px);
  }
}

/* Research Packet v2 / local research-gated intelligence engine. */
.packet-engine-shell,
.research-desk-shell,
.learning-ledger-v2 {
  --packet-bg: #08090b;
  --packet-panel: #101216;
  --packet-panel-2: #15181e;
  --packet-line: rgba(212, 175, 55, 0.18);
  --packet-gold: #d4af37;
  --packet-ivory: #f3eee2;
  --packet-muted: #9a9da5;
  --packet-green: #76b49b;
  --packet-red: #c66f67;
  min-width: 0;
  color: var(--packet-ivory);
}

.packet-engine-shell {
  display: grid;
  gap: 22px;
  padding: clamp(14px, 2vw, 28px);
  background:
    radial-gradient(circle at 82% 0%, rgba(212, 175, 55, 0.09), transparent 30%),
    var(--packet-bg);
}

.packet-engine-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 0.34fr);
  gap: 22px;
  align-items: end;
  min-width: 0;
  padding: clamp(24px, 4vw, 54px);
  border: 1px solid var(--packet-line);
  border-radius: 24px;
  background: linear-gradient(135deg, rgba(18, 20, 24, 0.98), rgba(8, 9, 11, 0.98));
}

.packet-engine-hero h2 {
  margin: 8px 0 12px;
  color: var(--packet-ivory);
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(48px, 8vw, 116px);
  line-height: 0.86;
  letter-spacing: -0.06em;
}

.packet-engine-hero p,
.packet-engine-hero small,
.packet-engine-shell p,
.packet-engine-shell li {
  color: var(--packet-muted);
  line-height: 1.55;
}

.packet-engine-hero > aside {
  display: grid;
  gap: 8px;
  min-width: 0;
  padding: 20px;
  border: 1px solid var(--packet-line);
  border-radius: 18px;
  background: rgba(212, 175, 55, 0.05);
}

.packet-engine-hero > aside span,
.packet-panel-head,
.packet-primary-panel article > span,
.packet-title-row > div > span {
  color: var(--packet-gold);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.packet-engine-hero > aside strong {
  font-size: 24px;
}

.packet-engine-hero > aside a {
  width: fit-content;
  margin-top: 8px;
  color: var(--packet-gold);
  font-weight: 800;
  text-decoration: none;
}

.packet-engine-layout {
  display: grid;
  grid-template-columns: minmax(220px, 0.7fr) minmax(0, 1.65fr) minmax(260px, 0.8fr);
  gap: 18px;
  align-items: start;
  min-width: 0;
}

.packet-queue-panel,
.packet-primary-panel,
.packet-evidence-rail > section,
.packet-vote-matrix,
.suppressed-noise-drawer,
.packet-archive-outcomes,
.packet-outcome-section,
.learning-memory-grid > article {
  min-width: 0;
  border: 1px solid var(--packet-line);
  border-radius: 18px;
  background: var(--packet-panel);
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.24);
}

.packet-queue-panel,
.packet-primary-panel,
.packet-evidence-rail > section,
.packet-vote-matrix,
.suppressed-noise-drawer,
.packet-archive-outcomes {
  padding: 18px;
}

.packet-panel-head {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--packet-line);
}

.packet-panel-head em {
  color: var(--packet-muted);
  font-style: normal;
  text-align: right;
}

.packet-queue-list {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}

.packet-queue-list button,
.suppressed-noise-list button {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px;
  width: 100%;
  min-width: 0;
  padding: 12px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 12px;
  background: #0b0d10;
  color: var(--packet-ivory);
  text-align: left;
}

.packet-queue-list button.active {
  border-color: rgba(212, 175, 55, 0.52);
  background: rgba(212, 175, 55, 0.08);
}

.packet-queue-list span,
.packet-queue-list em {
  display: block;
  min-width: 0;
}

.packet-queue-list em,
.suppressed-noise-list span {
  overflow-wrap: anywhere;
  color: var(--packet-muted);
  font-size: 10px;
  font-style: normal;
}

.packet-primary-panel {
  display: grid;
  gap: 16px;
}

.packet-title-row {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: start;
}

.packet-title-row h3 {
  margin: 6px 0 0;
  color: var(--packet-ivory);
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(28px, 3vw, 48px);
}

.packet-title-row > strong {
  flex: 0 0 auto;
  color: var(--packet-green);
  font-size: 22px;
}

.packet-title-row > strong.fatal,
.research-packet-head em.fatal {
  color: var(--packet-red);
}

.packet-route-banner {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid rgba(118, 180, 155, 0.34);
  border-radius: 12px;
  background: rgba(118, 180, 155, 0.08);
  color: var(--packet-green);
}

.packet-route-banner.fatal,
.packet-risk-gate.fatal,
#researchPacketPreview.fatal {
  border-color: rgba(198, 111, 103, 0.46);
  background: rgba(198, 111, 103, 0.08);
  color: var(--packet-red);
}

.packet-route-banner em {
  color: inherit;
  font-style: normal;
}

.packet-why-panel {
  padding: 16px;
  border-left: 3px solid var(--packet-gold);
  background: rgba(212, 175, 55, 0.055);
}

.packet-context-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.packet-context-grid article {
  min-width: 0;
  padding: 14px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 12px;
  background: #0b0d10;
}

.packet-context-grid p {
  margin: 7px 0 0;
  overflow-wrap: anywhere;
}

.options-alerts-panel {
  display: grid;
  gap: 14px;
  min-width: 0;
  padding: 16px;
  border: 1px solid rgba(212, 175, 55, 0.18);
  border-radius: 14px;
  background:
    linear-gradient(145deg, rgba(212, 175, 55, 0.035), transparent 42%),
    #0b0d10;
}

.options-alerts-panel-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 11px;
  border-bottom: 1px solid rgba(212, 175, 55, 0.16);
  color: var(--packet-gold);
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.options-alerts-panel-head em {
  color: var(--packet-muted);
  font-style: normal;
  letter-spacing: 0.04em;
  text-align: right;
}

.options-alerts-data-grid,
.options-alerts-copy-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}

.options-alerts-data-grid article,
.options-alerts-copy-grid article {
  display: grid;
  gap: 6px;
  min-width: 0;
  padding: 11px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  border-radius: 10px;
  background: rgba(17, 19, 23, 0.86);
}

.options-alerts-data-grid.identity {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.options-alerts-data-grid span,
.options-alerts-copy-grid span,
.options-alerts-evidence > span,
.options-alerts-output > span {
  color: var(--packet-gold);
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.options-alerts-data-grid strong,
.options-alerts-copy-grid strong {
  overflow-wrap: anywhere;
  color: var(--packet-ivory);
  font-size: 12px;
}

.options-alerts-copy-grid .wide {
  grid-column: 1 / -1;
}

.options-alerts-copy-grid p {
  margin: 0;
}

.options-alerts-ttt {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.options-alerts-ttt span {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 9px 10px;
  border: 1px solid rgba(212, 175, 55, 0.14);
  border-radius: 999px;
  color: var(--packet-muted);
  font-size: 10px;
  overflow-wrap: anywhere;
}

.options-alerts-ttt small {
  color: var(--packet-gold);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.options-alerts-source-summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.options-alerts-source-summary span {
  display: grid;
  gap: 4px;
  padding: 10px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  border-radius: 10px;
  background: rgba(17, 19, 23, 0.86);
}

.options-alerts-source-summary small {
  color: var(--packet-muted);
  font-size: 8px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.options-alerts-source-summary strong {
  color: var(--packet-ivory);
  font-size: 14px;
}

.options-alerts-definition-list {
  display: grid;
  gap: 8px;
  margin: 0;
}

.options-alerts-definition-list div {
  display: grid;
  gap: 4px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.065);
}

.options-alerts-definition-list dt {
  color: var(--packet-gold);
  font-size: 8px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.options-alerts-definition-list dd {
  margin: 0;
  overflow-wrap: anywhere;
  color: var(--packet-muted);
  font-size: 11px;
}

.options-alerts-evidence {
  padding: 11px;
  border-left: 2px solid var(--packet-green);
  background: rgba(118, 180, 155, 0.055);
}

.options-alerts-evidence.missing {
  border-left-color: var(--packet-gold);
  background: rgba(212, 175, 55, 0.055);
}

.options-alerts-evidence ul {
  margin-bottom: 0;
}

.options-alerts-state-key {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.options-alerts-state-key span {
  padding: 5px 7px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  color: var(--packet-muted);
  font-size: 8px;
  font-weight: 800;
  text-transform: uppercase;
}

.options-alerts-state-key span.active {
  border-color: rgba(212, 175, 55, 0.46);
  background: rgba(212, 175, 55, 0.1);
  color: var(--packet-gold);
}

.options-alerts-warning {
  margin: 0;
  padding: 11px 12px;
  border: 1px solid rgba(198, 111, 103, 0.24);
  border-radius: 10px;
  background: rgba(198, 111, 103, 0.055);
  color: var(--packet-muted);
  font-size: 11px;
}

.options-alerts-risk-list {
  display: grid;
  gap: 7px;
}

.options-alerts-risk-list article {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 9px;
  align-items: start;
  padding: 9px;
  border: 1px solid rgba(255, 255, 255, 0.065);
  border-radius: 10px;
  background: rgba(17, 19, 23, 0.86);
}

.options-alerts-risk-list article > span {
  min-width: 44px;
  padding: 4px 5px;
  border: 1px solid currentColor;
  border-radius: 999px;
  color: var(--packet-green);
  font-size: 7px;
  font-weight: 900;
  text-align: center;
}

.options-alerts-risk-list article.blocked > span {
  color: var(--packet-red);
}

.options-alerts-risk-list strong {
  display: block;
  margin: 0;
  color: var(--packet-ivory);
  font-size: 10px;
}

.options-alerts-risk-list p {
  margin: 3px 0 0;
  font-size: 9px;
}

.options-alerts-output {
  display: grid;
  gap: 5px;
  padding: 12px;
  border: 1px solid rgba(212, 175, 55, 0.22);
  border-radius: 10px;
  background: rgba(212, 175, 55, 0.055);
}

.options-alerts-output strong {
  color: var(--packet-ivory);
  font-size: 16px;
}

.options-alerts-output small {
  color: var(--packet-muted);
}

.packet-ceo-actions {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

.packet-ceo-actions button,
.packet-outcome-grid button {
  min-height: 40px;
  border: 1px solid rgba(212, 175, 55, 0.32);
  border-radius: 10px;
  background: rgba(212, 175, 55, 0.09);
  color: var(--packet-gold);
  font-weight: 850;
}

.packet-evidence-rail {
  display: grid;
  gap: 12px;
  min-width: 0;
}

.packet-evidence-rail ul {
  display: grid;
  gap: 7px;
  margin: 12px 0 0;
  padding-left: 18px;
}

.packet-evidence-rail strong {
  display: block;
  margin-top: 12px;
}

.packet-vote-matrix {
  overflow: hidden;
}

.packet-table-wrap {
  overflow-x: auto;
}

.packet-vote-matrix table {
  width: 100%;
  min-width: 620px;
  border-collapse: collapse;
}

.packet-vote-matrix th,
.packet-vote-matrix td {
  padding: 11px 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
  color: var(--packet-muted);
  text-align: left;
}

.packet-vote-matrix th {
  color: var(--packet-gold);
  font-size: 10px;
  text-transform: uppercase;
}

.packet-vote {
  display: inline-flex;
  padding: 4px 7px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 999px;
  font-size: 9px;
  font-weight: 900;
}

.packet-vote.support { color: var(--packet-green); }
.packet-vote.caution { color: var(--packet-gold); }
.packet-vote.block,
.packet-vote.needs_evidence { color: var(--packet-red); }

.suppressed-noise-drawer summary,
.packet-archive-outcomes summary {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: var(--packet-ivory);
  cursor: pointer;
  font-weight: 850;
}

.suppressed-noise-list {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}

.research-desk-shell .research-builder-grid {
  grid-template-columns: minmax(0, 1.8fr) minmax(280px, 0.72fr);
}

.research-desk-shell .research-builder-card {
  grid-row: span 2;
}

.research-form-grid input,
.research-form-grid textarea,
.research-form-grid select,
.packet-outcome-grid select,
.packet-outcome-grid textarea {
  width: 100%;
  min-width: 0;
  border: 1px solid rgba(212, 175, 55, 0.18);
  border-radius: 9px;
  background: #090a0c;
  color: #f3eee2;
  padding: 10px;
}

.research-form-grid textarea {
  min-height: 82px;
  resize: vertical;
}

.research-preview-bands {
  display: grid;
  gap: 7px;
  margin: 16px 0;
}

.research-preview-bands span {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 10px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 9px;
}

/* Finance Terminal static/manual cockpit — #/research owner route only. */
.finance-terminal-module {
  display: grid;
  gap: 18px;
  min-width: 0;
  padding: clamp(18px, 2.8vw, 34px);
  border: 1px solid rgba(212, 175, 55, 0.36);
  border-radius: 22px;
  background:
    linear-gradient(90deg, rgba(212, 175, 55, 0.045) 1px, transparent 1px),
    linear-gradient(rgba(212, 175, 55, 0.035) 1px, transparent 1px),
    radial-gradient(circle at 4% 0%, rgba(212, 175, 55, 0.13), transparent 30%),
    linear-gradient(145deg, rgba(14, 16, 19, 0.99), rgba(5, 6, 8, 0.99));
  background-size: 38px 38px, 38px 38px, auto, auto;
  box-shadow: 0 30px 76px rgba(0, 0, 0, 0.4);
}

.finance-terminal-head,
.finance-terminal-section-head {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
}

.finance-terminal-head h3,
.finance-terminal-section-head h4 {
  margin: 7px 0 5px;
  color: var(--packet-ivory);
  font-family: Georgia, "Times New Roman", serif;
}

.finance-terminal-head h3 {
  max-width: 760px;
  font-size: clamp(28px, 4vw, 50px);
  letter-spacing: -0.035em;
}

.finance-terminal-head p,
.finance-terminal-section-head > span,
.finance-terminal-form-note,
.finance-terminal-readiness > p {
  margin: 0;
  color: var(--packet-muted);
}

.finance-terminal-boundaries,
.finance-terminal-preview-badges,
.finance-terminal-indicators,
.finance-terminal-handoffs > div {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.finance-terminal-boundaries {
  max-width: 540px;
  justify-content: flex-end;
}

.finance-terminal-boundaries span,
.finance-terminal-preview-badges :is(strong, em),
.finance-terminal-indicators em,
.finance-terminal-handoffs em {
  padding: 6px 9px;
  border: 1px solid rgba(212, 175, 55, 0.25);
  border-radius: 999px;
  background: rgba(212, 175, 55, 0.065);
  color: var(--packet-gold);
  font-size: 8px;
  font-style: normal;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.finance-terminal-layout {
  display: grid;
  grid-template-columns: minmax(310px, 0.7fr) minmax(0, 1.3fr);
  gap: 18px;
  align-items: start;
  min-width: 0;
}

.finance-terminal-composer,
.finance-terminal-readiness {
  min-width: 0;
  padding: 18px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 16px;
  background: rgba(8, 10, 12, 0.94);
}

.finance-terminal-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 16px;
}

.finance-terminal-field {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 138px;
  gap: 7px;
  min-width: 0;
  color: var(--packet-gold);
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.055em;
  text-transform: uppercase;
}

.finance-terminal-field > span {
  grid-column: 1 / -1;
}

.finance-terminal-field.wide {
  grid-column: 1 / -1;
}

.finance-terminal-field input,
.finance-terminal-field textarea,
.finance-terminal-field select {
  width: 100%;
  min-width: 0;
  padding: 9px;
  border: 1px solid rgba(212, 175, 55, 0.2);
  border-radius: 9px;
  background: #06080a;
  color: var(--packet-ivory);
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
}

.finance-terminal-field textarea {
  min-height: 66px;
  resize: vertical;
}

.finance-terminal-field .finance-terminal-state-select {
  color: var(--packet-gold);
  font-size: 8px;
  font-weight: 800;
  text-transform: uppercase;
}

.finance-terminal-form-note {
  padding-top: 14px;
  font-size: 10px;
  line-height: 1.55;
}

.finance-terminal-output-stack {
  display: grid;
  gap: 14px;
  min-width: 0;
}

.finance-terminal-cockpit {
  min-width: 0;
  overflow: hidden;
  border: 1px solid rgba(212, 175, 55, 0.44);
  border-radius: 18px;
  background: #07090b;
  box-shadow: 0 22px 54px rgba(0, 0, 0, 0.44);
}

.finance-terminal-cockpit.output-no_output {
  border-color: rgba(198, 111, 103, 0.58);
}

.finance-terminal-cockpit.output-public_ready_candidate {
  border-color: rgba(118, 180, 155, 0.62);
}

.finance-terminal-preview-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 0.8fr);
  gap: 14px;
  align-items: center;
  padding: 18px;
  border-bottom: 1px solid rgba(212, 175, 55, 0.17);
  background: linear-gradient(100deg, rgba(212, 175, 55, 0.13), rgba(10, 12, 15, 0.98) 64%);
}

.finance-terminal-preview-head span,
.finance-terminal-preview-grid > section > span,
.finance-terminal-score-grid span,
.finance-terminal-blocks > span {
  color: var(--packet-gold);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.finance-terminal-preview-head h4 {
  margin: 5px 0 2px;
  overflow-wrap: anywhere;
  color: var(--packet-ivory);
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(22px, 2.8vw, 38px);
}

.finance-terminal-preview-head p,
.finance-terminal-preview-grid p,
.finance-terminal-preview-grid dd,
.finance-terminal-preview-grid small {
  overflow-wrap: anywhere;
  color: var(--packet-muted);
  font-size: 10px;
  line-height: 1.45;
}

.finance-terminal-preview-badges {
  justify-content: flex-end;
}

.finance-terminal-preview-badges :is(strong, em) {
  max-width: 100%;
  overflow-wrap: anywhere;
}

.finance-terminal-preview-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.finance-terminal-preview-grid > section {
  min-width: 0;
  padding: 16px;
  border-right: 1px solid rgba(255, 255, 255, 0.065);
  border-bottom: 1px solid rgba(255, 255, 255, 0.065);
}

.finance-terminal-preview-grid > section:nth-child(even) {
  border-right: 0;
}

.finance-terminal-preview-grid h5 {
  margin: 7px 0 6px;
  overflow-wrap: anywhere;
  color: var(--packet-ivory);
  font-size: 14px;
}

.finance-terminal-preview-grid dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  margin: 10px 0;
}

.finance-terminal-preview-grid dl div {
  min-width: 0;
  padding: 7px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.02);
}

.finance-terminal-preview-grid dt {
  color: var(--packet-gold);
  font-size: 7px;
  font-weight: 850;
  text-transform: uppercase;
}

.finance-terminal-preview-grid dd {
  margin: 3px 0 0;
  color: var(--packet-ivory);
}

.finance-terminal-preview-grid dd small {
  display: block;
  color: var(--packet-gold);
  font-size: 6px;
  text-transform: uppercase;
}

.finance-terminal-compact-dl {
  grid-template-columns: 1fr !important;
}

.finance-terminal-indicators {
  margin-top: 10px;
}

.finance-terminal-indicators em {
  padding: 4px 6px;
  font-size: 6px;
}

.finance-terminal-scenarios > div {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  margin-top: 10px;
}

.finance-terminal-scenarios article {
  min-width: 0;
  padding: 9px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.02);
}

.finance-terminal-scenarios article.bull {
  border-color: rgba(118, 180, 155, 0.34);
}

.finance-terminal-scenarios article.bear,
.finance-terminal-scenarios article.risk {
  border-color: rgba(198, 111, 103, 0.34);
}

.finance-terminal-scenarios article.wide {
  grid-column: 1 / -1;
}

.finance-terminal-scenarios strong {
  color: var(--packet-ivory);
  font-size: 9px;
}

.finance-terminal-decision > div {
  display: grid;
  gap: 5px;
  margin-top: 9px;
}

.finance-terminal-decision strong {
  color: var(--packet-ivory);
  font-size: 26px;
}

.finance-terminal-decision em {
  color: var(--packet-gold);
  font-size: 10px;
  font-style: normal;
  font-weight: 850;
}

.finance-terminal-handoffs {
  grid-column: 1 / -1;
  border-right: 0 !important;
}

.finance-terminal-handoffs > div {
  margin-top: 10px;
}

.finance-terminal-safety-footer {
  padding: 14px 18px;
  background: rgba(212, 175, 55, 0.09);
  color: var(--packet-ivory);
  font-size: 9px;
  font-weight: 750;
  line-height: 1.55;
  text-align: center;
}

.finance-terminal-readiness {
  display: grid;
  gap: 13px;
}

.finance-terminal-section-head > strong {
  color: var(--packet-gold);
  font-size: 22px;
}

.finance-terminal-score-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
}

.finance-terminal-score-grid div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 9px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.025);
}

.finance-terminal-score-grid strong {
  color: var(--packet-ivory);
  font-size: 10px;
}

.finance-terminal-blocks {
  padding: 12px;
  border: 1px solid rgba(118, 180, 155, 0.28);
  border-radius: 11px;
  background: rgba(118, 180, 155, 0.05);
}

.finance-terminal-blocks.blocked {
  border-color: rgba(198, 111, 103, 0.36);
  background: rgba(198, 111, 103, 0.065);
}

.finance-terminal-blocks ul {
  margin: 9px 0 0;
  padding-left: 17px;
  color: var(--packet-muted);
  font-size: 10px;
}

.finance-terminal-blocks p {
  margin: 8px 0 0;
  color: var(--packet-muted);
  font-size: 10px;
}

/* Pickaxe X static/manual preview — #/research owner route only. */
.pickaxe-x-preview-module {
  display: grid;
  gap: 18px;
  min-width: 0;
  padding: clamp(18px, 2.8vw, 34px);
  border: 1px solid rgba(212, 175, 55, 0.28);
  border-radius: 22px;
  background:
    radial-gradient(circle at 88% 0%, rgba(212, 175, 55, 0.1), transparent 32%),
    linear-gradient(145deg, rgba(18, 20, 24, 0.98), rgba(7, 8, 10, 0.98));
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.34);
}

.pickaxe-x-module-head,
.pickaxe-x-section-head {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
}

.pickaxe-x-module-head h3,
.pickaxe-x-section-head h4 {
  margin: 7px 0 5px;
  color: var(--packet-ivory);
  font-family: Georgia, "Times New Roman", serif;
}

.pickaxe-x-module-head h3 {
  font-size: clamp(28px, 4vw, 50px);
  letter-spacing: -0.035em;
}

.pickaxe-x-module-head p,
.pickaxe-x-section-head > span,
.pickaxe-x-form-note,
.pickaxe-x-qa-panel > p {
  margin: 0;
  color: var(--packet-muted);
}

.pickaxe-x-default-badges,
.pickaxe-x-context-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.pickaxe-x-default-badges {
  max-width: 510px;
  justify-content: flex-end;
}

.pickaxe-x-default-badges span,
.pickaxe-x-context-chips em {
  padding: 6px 9px;
  border: 1px solid rgba(212, 175, 55, 0.24);
  border-radius: 999px;
  background: rgba(212, 175, 55, 0.06);
  color: var(--packet-gold);
  font-size: 8px;
  font-style: normal;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.pickaxe-x-workspace {
  display: grid;
  grid-template-columns: minmax(300px, 0.72fr) minmax(0, 1.28fr);
  gap: 18px;
  align-items: start;
  min-width: 0;
}

.pickaxe-x-composer,
.pickaxe-x-qa-panel {
  min-width: 0;
  padding: 18px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 16px;
  background: rgba(10, 11, 13, 0.9);
}

.pickaxe-x-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin-top: 16px;
}

.pickaxe-x-field {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 112px;
  gap: 7px;
  min-width: 0;
  color: var(--packet-gold);
  font-size: 9px;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.pickaxe-x-field > span {
  grid-column: 1 / -1;
}

.pickaxe-x-field.wide {
  grid-column: 1 / -1;
}

.pickaxe-x-field input,
.pickaxe-x-field textarea,
.pickaxe-x-field select {
  width: 100%;
  min-width: 0;
  padding: 9px;
  border: 1px solid rgba(212, 175, 55, 0.18);
  border-radius: 9px;
  background: #07080a;
  color: var(--packet-ivory);
  font-size: 11px;
  letter-spacing: 0;
  text-transform: none;
}

.pickaxe-x-field textarea {
  min-height: 66px;
  resize: vertical;
}

.pickaxe-x-field .pickaxe-x-state-select {
  color: var(--packet-gold);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
}

.pickaxe-x-form-note {
  padding-top: 14px;
  font-size: 10px;
  line-height: 1.55;
}

.pickaxe-x-output-stack {
  display: grid;
  gap: 14px;
  min-width: 0;
}

.pickaxe-x-card {
  display: grid;
  grid-template-rows: 0.62fr 1.38fr 0.94fr 1.42fr 0.78fr;
  width: 100%;
  min-width: 0;
  aspect-ratio: 1 / 1;
  overflow: hidden;
  border: 1px solid rgba(212, 175, 55, 0.42);
  border-radius: 18px;
  background: #08090b;
  box-shadow: 0 22px 54px rgba(0, 0, 0, 0.42);
}

.pickaxe-x-card.output-no_output {
  border-color: rgba(198, 111, 103, 0.56);
}

.pickaxe-x-card.output-public_ready_candidate {
  border-color: rgba(118, 180, 155, 0.58);
}

.pickaxe-x-band {
  min-width: 0;
  padding: clamp(10px, 1.5vw, 18px);
  border-bottom: 1px solid rgba(212, 175, 55, 0.16);
}

.pickaxe-x-band:last-child {
  border-bottom: 0;
}

.pickaxe-x-band span,
.pickaxe-x-band dt,
.pickaxe-x-qa-grid span,
.pickaxe-x-block-list > span {
  color: var(--packet-gold);
  font-size: clamp(7px, 0.7vw, 9px);
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pickaxe-x-band p,
.pickaxe-x-band dd,
.pickaxe-x-band small {
  overflow-wrap: anywhere;
  color: var(--packet-muted);
  font-size: clamp(8px, 0.82vw, 11px);
  line-height: 1.42;
}

.pickaxe-x-hero-band,
.pickaxe-x-decision-band {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  background: linear-gradient(100deg, rgba(212, 175, 55, 0.11), rgba(14, 16, 20, 0.97) 62%);
}

.pickaxe-x-hero-band h4 {
  margin: 5px 0 2px;
  overflow-wrap: anywhere;
  color: var(--packet-ivory);
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(19px, 2.4vw, 34px);
}

.pickaxe-x-hero-band > strong {
  padding: 7px 9px;
  border: 1px solid currentColor;
  border-radius: 999px;
  color: var(--packet-gold);
  font-size: 8px;
  text-transform: uppercase;
}

.pickaxe-x-market-band {
  display: grid;
  grid-template-columns: minmax(0, 1.5fr) minmax(150px, 0.7fr);
  gap: 12px;
}

.pickaxe-x-chart-placeholder {
  display: grid;
  place-content: center;
  gap: 7px;
  min-width: 0;
  padding: 12px;
  border: 1px dashed rgba(212, 175, 55, 0.32);
  border-radius: 12px;
  background:
    linear-gradient(rgba(212, 175, 55, 0.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(212, 175, 55, 0.035) 1px, transparent 1px),
    #0b0d10;
  background-size: 22px 22px;
  text-align: center;
}

.pickaxe-x-chart-placeholder strong {
  overflow-wrap: anywhere;
  color: var(--packet-ivory);
  font-size: clamp(12px, 1.25vw, 18px);
}

.pickaxe-x-market-band dl {
  display: grid;
  align-content: center;
  gap: 8px;
  margin: 0;
}

.pickaxe-x-market-band dl div {
  padding-bottom: 7px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.pickaxe-x-market-band dd {
  margin: 3px 0 0;
}

.pickaxe-x-context-band {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  align-content: center;
}

.pickaxe-x-context-band > div:not(.pickaxe-x-context-chips) {
  min-width: 0;
  padding: 9px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.02);
}

.pickaxe-x-context-band strong {
  display: block;
  margin-top: 4px;
  overflow-wrap: anywhere;
  color: var(--packet-ivory);
  font-size: clamp(8px, 0.85vw, 11px);
}

.pickaxe-x-context-chips {
  grid-column: 1 / -1;
}

.pickaxe-x-context-chips em {
  padding: 4px 6px;
  font-size: 6px;
}

.pickaxe-x-scenario-band {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  align-content: center;
}

.pickaxe-x-scenario-band article {
  min-width: 0;
  padding: 9px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.02);
}

.pickaxe-x-scenario-band article.bull {
  border-color: rgba(118, 180, 155, 0.34);
}

.pickaxe-x-scenario-band article.bear,
.pickaxe-x-scenario-band article.risk {
  border-color: rgba(198, 111, 103, 0.34);
}

.pickaxe-x-scenario-band article.wide {
  grid-column: span 3;
}

.pickaxe-x-scenario-band p {
  margin: 5px 0 0;
}

.pickaxe-x-decision-band {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  align-items: start;
}

.pickaxe-x-decision-band div {
  min-width: 0;
}

.pickaxe-x-decision-band strong {
  display: block;
  margin: 4px 0 2px;
  overflow-wrap: anywhere;
  color: var(--packet-ivory);
  font-size: clamp(10px, 1vw, 14px);
}

.pickaxe-x-decision-band > p {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--packet-ivory);
  font-size: clamp(7px, 0.7vw, 9px);
}

.pickaxe-x-qa-panel {
  display: grid;
  gap: 13px;
}

.pickaxe-x-section-head > strong {
  color: var(--packet-gold);
  font-size: 22px;
}

.pickaxe-x-qa-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
}

.pickaxe-x-qa-grid div {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 9px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.025);
}

.pickaxe-x-qa-grid strong {
  color: var(--packet-ivory);
  font-size: 10px;
}

.pickaxe-x-block-list {
  padding: 12px;
  border: 1px solid rgba(118, 180, 155, 0.28);
  border-radius: 11px;
  background: rgba(118, 180, 155, 0.05);
}

.pickaxe-x-block-list.blocked {
  border-color: rgba(198, 111, 103, 0.34);
  background: rgba(198, 111, 103, 0.06);
}

.pickaxe-x-block-list ul {
  margin: 9px 0 0;
  padding-left: 17px;
  color: var(--packet-muted);
  font-size: 10px;
}

.pickaxe-x-block-list p {
  margin: 8px 0 0;
  color: var(--packet-muted);
  font-size: 10px;
}

.research-route-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

.learning-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.learning-summary-grid article {
  display: grid;
  gap: 7px;
  padding: 18px;
  border: 1px solid var(--packet-line);
  border-radius: 14px;
  background: var(--packet-panel);
}

.learning-summary-grid span {
  color: var(--packet-muted);
}

.learning-summary-grid strong {
  color: var(--packet-gold);
  font-size: 28px;
}

.packet-outcome-section,
.packet-archive-outcomes {
  padding: clamp(18px, 2.5vw, 32px);
}

.packet-outcome-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 16px;
}

.packet-outcome-grid > article {
  display: grid;
  gap: 11px;
  min-width: 0;
  padding: 16px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  background: #0b0d10;
}

.packet-outcome-grid label {
  display: grid;
  gap: 6px;
  color: var(--packet-gold);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.packet-outcome-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  color: var(--packet-gold);
}

.packet-outcome-head em {
  color: var(--packet-muted);
  font-style: normal;
}

.learning-memory-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 0.72fr);
  gap: 14px;
}

.learning-memory-grid > article {
  padding: 20px;
}

.learning-memory-grid .glass-card p {
  display: grid;
  gap: 5px;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.research-empty-state {
  padding: 18px;
  border: 1px dashed rgba(212, 175, 55, 0.22);
  border-radius: 12px;
  color: var(--packet-muted);
}

@media (max-width: 1180px) {
  .packet-engine-layout,
  .research-desk-shell .research-builder-grid,
  .finance-terminal-layout,
  .pickaxe-x-workspace {
    grid-template-columns: 1fr;
  }

  .pickaxe-x-card {
    max-width: 820px;
    margin: 0 auto;
  }

  .packet-queue-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .packet-engine-hero,
  .packet-context-grid,
  .packet-outcome-grid,
  .learning-memory-grid,
  .learning-summary-grid {
    grid-template-columns: 1fr;
  }

  .packet-engine-hero {
    padding: 22px;
  }

  .packet-engine-hero h2 {
    font-size: clamp(44px, 17vw, 76px);
  }

  .packet-title-row,
  .packet-route-banner,
  .packet-panel-head,
  .options-alerts-panel-head,
  .finance-terminal-head,
  .finance-terminal-section-head,
  .pickaxe-x-module-head,
  .pickaxe-x-section-head {
    align-items: start;
    flex-direction: column;
  }

  .packet-ceo-actions,
  .packet-queue-list,
  .options-alerts-data-grid,
  .options-alerts-data-grid.identity,
  .options-alerts-copy-grid,
  .options-alerts-source-summary,
  .options-alerts-ttt {
    grid-template-columns: 1fr;
  }

  .options-alerts-copy-grid .wide {
    grid-column: auto;
  }

  .pickaxe-x-default-badges {
    max-width: none;
    justify-content: flex-start;
  }

  .finance-terminal-boundaries,
