}

.phase3-department-panel,
.phase3-agent-inspector,
.phase3-task-board,
.phase3-workflow-rail,
.phase3-command-panel,
.phase3-truth-panel,
.phase3-activity-strip,
.phase3-system-map,
.phase3-os-pipeline,
.phase3-ownership-panel,
.phase3-manual-gate,
