  border-radius: 999px;
  color: var(--phase3-gold-bright);
  background: rgba(199, 164, 91, 0.07);
  font: 600 9px/1.2 var(--phase2-font-mono, monospace);
  letter-spacing: 0.08em;
  text-decoration: none;
  text-transform: uppercase;
}

.phase3-department-grid {
