  align-content: start;
  gap: 8px;
  min-width: 0;
  min-height: 202px;
  padding: 16px;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 13px;
  color: var(--phase3-text);
  background: rgba(8, 9, 11, 0.76);
  text-align: left;
  cursor: pointer;
  transition: transform 160ms ease, border-color 160ms ease, background 160ms ease;
}

button.phase3-department-card:hover,
button.phase3-department-card.is-selected {
  transform: translateY(-2px);
  border-color: rgba(227, 199, 127, 0.62);
