  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.phase3-review-note p,
.phase3-risk-boundary p,
.phase3-manual-next strong {
  margin: 0;
  color: #c4c8cf;
  font-size: 10px;
  line-height: 1.45;
}

.phase3-task-composer {
