  gap: 10px;
  align-items: center;
  margin-bottom: 14px;
  padding: 12px;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 12px;
  background: rgba(0,0,0,0.24);
}

.phase3-task-composer label {
  color: #c7c3bb;
  font-size: 11px;
  line-height: 1.35;
}

.phase3-task-composer input {
