  min-width: 0;
  min-height: 42px;
  padding: 0 12px;
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 8px;
  color: var(--phase3-text);
  background: #090a0d;
}

.phase3-task-grid {
