  gap: 8px;
  min-width: 0;
  min-height: 132px;
  padding: 13px;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
  color: inherit;
  background: rgba(0,0,0,0.26);
  text-decoration: none;
}

.phase3-rail-grid a:not(:last-child)::after {
