}

.phase3-rail-grid span {
  color: var(--phase3-gold);
  font: 700 9px/1 var(--phase2-font-mono, monospace);
}

.phase3-rail-grid strong {
  color: var(--phase3-text);
  font-size: 12px;
}

.phase3-rail-grid small {
