}

.phase3-activity-strip {
  padding: 17px 20px;
}

.phase3-activity-strip > div {
  display: grid;
  gap: 6px;
  margin-top: 10px;
}

.phase3-activity-strip p {
  display: grid;
  grid-template-columns: minmax(120px, 0.25fr) 1fr auto;
  gap: 12px;
  margin: 0;
  padding-top: 7px;
  border-top: 1px solid rgba(255,255,255,0.07);
  color: var(--phase3-muted);
  font-size: 10px;
}

.phase3-activity-strip strong {
  color: var(--phase3-gold-bright);
}

.phase3-system-map {
  overflow: hidden;
}

.phase3-zone-map {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-template-rows: repeat(3, minmax(116px, auto));
  gap: 10px;
}

.phase3-zone-map::before,
.phase3-zone-map::after {
  content: "";
  position: absolute;
  z-index: 0;
  background: linear-gradient(90deg, transparent, rgba(199,164,91,0.4), transparent);
}

.phase3-zone-map::before {
  top: 50%;
  left: 8%;
  right: 8%;
  height: 1px;
}

.phase3-zone-map::after {
  top: 8%;
  bottom: 8%;
  left: 50%;
  width: 1px;
}

.phase3-zone-card,
.phase3-map-core {
  position: relative;
  z-index: 1;
  display: grid;
  align-content: center;
  gap: 7px;
  min-width: 0;
  padding: 15px;
  border: 1px solid rgba(255,255,255,0.09);
  border-radius: 12px;
  color: inherit;
  background: rgba(8,9,11,0.91);
  text-decoration: none;
}

.phase3-zone-card span,
.phase3-map-core span {
  color: var(--phase3-gold);
  font: 700 9px/1 var(--phase2-font-mono, monospace);
  letter-spacing: 0.12em;
}

.phase3-zone-card strong,
.phase3-map-core strong {
