  font-size: 14px;
}

.phase3-zone-card small,
.phase3-zone-card em,
.phase3-map-core small {
  color: var(--phase3-muted);
  font-size: 9px;
  font-style: normal;
}

.phase3-map-core {
  grid-column: 2 / 4;
  grid-row: 2;
  border-color: rgba(227,199,127,0.62);
  background: radial-gradient(circle at 50% 50%, rgba(199,164,91,0.18), rgba(8,9,11,0.96) 70%);
