  box-shadow: 0 0 40px rgba(199,164,91,0.1);
}

.phase3-zone-card.zone-1 { grid-column: 1; grid-row: 1; }
.phase3-zone-card.zone-2 { grid-column: 2; grid-row: 1; }
.phase3-zone-card.zone-3 { grid-column: 3; grid-row: 1; }
.phase3-zone-card.zone-4 { grid-column: 4; grid-row: 1; }
.phase3-zone-card.zone-5 { grid-column: 1; grid-row: 2; }
.phase3-zone-card.zone-6 { grid-column: 4; grid-row: 2; }
.phase3-zone-card.zone-7 { grid-column: 1; grid-row: 3; }
.phase3-zone-card.zone-8 { grid-column: 2 / 4; grid-row: 3; }
.phase3-zone-card.zone-9 { grid-column: 4; grid-row: 3; }

