  color: var(--phase3-gold-bright);
  font: 700 9px/1 var(--phase2-font-mono, monospace);
}

.phase3-os-pipeline strong {
  color: var(--phase3-text);
  font-size: 11px;
  line-height: 1.3;
}

.phase3-os-pipeline p {
