.phase3-manual-gate > div {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.phase3-manual-gate > div span {
  padding: 7px 9px;
  border: 1px solid rgba(201,99,84,0.3);
  border-radius: 999px;
  color: #d9b2aa;
  background: rgba(201,99,84,0.07);
  font-size: 9px;
}

.phase3-manual-gate .primary-action {
