/* Alerts Structure v1 — preserve deep systems while keeping the default route concise. */
#alerts.active .alerts-advanced-research {
  display: grid;
  gap: 0;
  margin: 18px 0;
  border: 1px solid rgba(212, 175, 55, 0.24);
  border-radius: 13px;
  background:
    linear-gradient(145deg, rgba(212, 175, 55, 0.045), transparent 48%),
    rgba(5, 7, 9, 0.86);
  box-shadow: inset 0 1px rgba(255, 248, 225, 0.035), 0 18px 48px rgba(0, 0, 0, 0.24);
}

#alerts.active .alerts-advanced-research > summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 16px;
  align-items: center;
  min-height: 76px;
  padding: 16px 18px;
  cursor: pointer;
  list-style: none;
}

#alerts.active .alerts-advanced-research > summary::-webkit-details-marker {
  display: none;
}

#alerts.active .alerts-advanced-research > summary::after {
  content: "+";
  grid-column: 2;
  grid-row: 1;
  display: grid;
  width: 30px;
  height: 30px;
  place-content: center;
  margin-left: 8px;
  border: 1px solid rgba(212, 175, 55, 0.32);
  border-radius: 50%;
  color: #d8b65e;
  font: 700 17px/1 var(--phase2-font-mono);
}

#alerts.active .alerts-advanced-research[open] > summary::after {
  content: "−";
}

#alerts.active .alerts-advanced-research > summary > span {
  display: grid;
  gap: 5px;
  min-width: 0;
}

#alerts.active .alerts-advanced-research > summary strong {
  color: #eee8dc;
  font: 600 clamp(18px, 2vw, 25px)/1.1 var(--phase2-font-display);
  letter-spacing: -0.02em;
}

#alerts.active .alerts-advanced-research > summary small {
  color: #8f8b83;
  font-size: 9px;
  line-height: 1.45;
}

#alerts.active .alerts-advanced-research > summary em {
  grid-column: 2;
  grid-row: 2;
  color: #b99a51;
  font: 750 8px/1.35 var(--phase2-font-mono);
  font-style: normal;
  text-align: right;
  text-transform: uppercase;
}

#alerts.active .alerts-advanced-research > summary:hover,
#alerts.active .alerts-advanced-research > summary:focus-visible {
  background: rgba(212, 175, 55, 0.045);
  outline: none;
}

#alerts.active .alerts-advanced-research > summary:focus-visible {
  box-shadow: inset 0 0 0 2px rgba(238, 206, 126, 0.5);
}

#alerts.active .alerts-advanced-research-body {
  display: grid;
  gap: 18px;
  padding: 0 18px 18px;
  border-top: 1px solid rgba(212, 175, 55, 0.14);
}

